import * as Config from "./src/config.js";
import {FruitopiaCore,createDefaultState,migrateSave,serializeState,xpForLevel,levelTitle,total,clamp} from "./src/core.js";
import {FruitopiaWorld} from "./src/world.js";
import {MiniGameController} from "./src/minigames.js";
import {MafiaGameEngine} from "./src/mafia-game.js";

const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const escapeHtml=value=>String(value??"").replace(/[&<>'"]/g,character=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[character]);
const money=value=>`$${Math.max(0,Number(value)||0).toLocaleString(undefined,{maximumFractionDigits:1})}`;
const fruitName=id=>Config.FRUIT_BY_ID[id]?.name||id;
const productName=id=>Config.RECIPE_BY_ID[id]?.name||id;
const formatItems=(items,type="fruit")=>Object.entries(items||{}).map(([item,amount])=>`${amount} ${type==="fruit"?fruitName(item):productName(item)}`).join(", ")||"None";
const remaining=timestamp=>Math.max(0,Math.ceil((timestamp-Date.now())/1000));

function readSave(){
  try{
    const current=localStorage.getItem(Config.SAVE_KEY);if(current)return migrateSave(JSON.parse(current));
    for(const key of Config.LEGACY_SAVE_KEYS){const value=localStorage.getItem(key);if(value)return migrateSave(JSON.parse(value));}
  }catch(error){console.warn("Fruitopia save was repaired",error);}
  return createDefaultState();
}

const core=new FruitopiaCore(readSave());
const mafiaGame=new MafiaGameEngine(core);
const offline=core.applyOfflineProgress(Date.now());
let world,minigame=null,currentView={page:null,sub:null},lastFocused=null,audioContext=null,musicTimer=null;
if(!core.state.phone.orders.length)core.generateOrder();

function save(){try{localStorage.setItem(Config.SAVE_KEY,serializeState(core.state));$("#saveStatus").textContent="Saved just now";}catch(error){console.warn("Save failed",error);$("#saveStatus").textContent="Save unavailable";}}
function tone(kind="success"){
  if(!core.state.settings.sound)return;
  try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==="suspended")audioContext.resume();const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),now=audioContext.currentTime;const frequencies={success:660,error:170,coin:880,harvest:520,purchase:430,level:760,countdown:300};oscillator.frequency.setValueAtTime(frequencies[kind]||520,now);oscillator.frequency.exponentialRampToValueAtTime((frequencies[kind]||520)*1.2,now+.13);gain.gain.setValueAtTime(.055,now);gain.gain.exponentialRampToValueAtTime(.001,now+.18);oscillator.connect(gain).connect(audioContext.destination);oscillator.start(now);oscillator.stop(now+.2);}catch{}
}
function updateMusic(){clearInterval(musicTimer);musicTimer=null;if(!core.state.settings.music)return;musicTimer=setInterval(()=>tone("harvest"),5000);}
function toast(title,message,type="info"){const node=document.createElement("div");node.className=`toast ${type}`;const strong=document.createElement("strong"),span=document.createElement("span");strong.textContent=title;span.textContent=message;node.append(strong,span);$("#toastRegion").prepend(node);setTimeout(()=>node.remove(),4800);}
function feedback(result,title="Fruitopia"){toast(result.ok?title:"Action unavailable",result.message,result.ok?"info":"error");tone(result.ok?"success":"error");updateUI();save();return result;}

function dialogShell(title,icon,body,kicker="FRUITOPIA COMPANY",className=""){
  return `<header class="dialog-header"><div class="dialog-title"><span aria-hidden="true">${icon}</span><div><small>${kicker}</small><h2 id="dialogTitle">${escapeHtml(title)}</h2></div></div><button class="close-button" data-action="close-dialog" aria-label="Close dialog">×</button></header>${body}`;
}
function tabs(items,active){return `<nav class="dialog-tabs" aria-label="Section tabs">${items.map(([id,label])=>`<button data-do="subpage" data-value="${id}" class="${id===active?"active":""}">${label}</button>`).join("")}</nav>`;}
function openDialog(title,icon,body,{kicker,className=""}={}){lastFocused=document.activeElement;const layer=$("#dialogLayer"),dialog=$("#dialog");dialog.className=`dialog ${className}`;dialog.innerHTML=dialogShell(title,icon,body,kicker);layer.classList.remove("hidden");layer.setAttribute("aria-hidden","false");setTimeout(()=>(dialog.querySelector("button:not([disabled]),input,select")||dialog).focus?.(),0);}
function closeDialog(){if(minigame){minigame.destroy();minigame=null;}const layer=$("#dialogLayer");layer.classList.add("hidden");layer.setAttribute("aria-hidden","true");$("#dialog").replaceChildren();currentView={page:null,sub:null};lastFocused?.focus?.();}
function rerender(){if(currentView.page)openPage(currentView.page,currentView.sub,true);}

function updateUI(){
  core.recalculate();const state=core.state,basket=total(state.fruitInventory),warehouse=total(state.productInventory),next=xpForLevel(Math.min(18,state.level+1));
  $("#cashValue").textContent=money(state.cash);$("#coinValue").textContent=state.fruitCoins;$("#basketValue").textContent=`${basket} / ${state.basketCapacity}`;$("#warehouseValue").textContent=`${warehouse} / ${state.warehouseCapacity}`;$("#passiveValue").textContent=`+${money(core.passiveIncomePerMinute())}/min`;$("#levelValue").textContent=`Level ${state.level}`;$("#levelTitle").textContent=levelTitle(state.level);$("#xpValue").textContent=state.level>=18?`${state.xp.toLocaleString()} XP · MAX`:`${state.xp.toLocaleString()} / ${next.toLocaleString()} XP`;
  $("#reputationValue").textContent=Math.round(state.reputation);const workers=Object.values(state.workers);$("#happinessValue").textContent=`${Math.round(workers.reduce((sum,worker)=>sum+worker.happiness,0)/Math.max(1,workers.length))}%`;$("#researchValue").textContent=`${state.researchPoints} RP`;$("#soundToggle").textContent=state.settings.sound?"🔊":"🔇";document.body.classList.toggle("reduced-motion",state.settings.reducedMotion);
  const unread=state.phone.messages.filter(message=>message.unread).length,badge=$("#messageBadge");badge.textContent=unread;badge.classList.toggle("hidden",!unread);
  renderQuestSide();renderRequestSide();renderCoach();
  const district=Config.DISTRICT_BY_ID[state.player.district]||Config.DISTRICTS[0],sewerActive=state.sewer.active;$("#districtStatus").textContent=sewerActive?`Underground · ${(state.sewer.player.section||"sewer").replaceAll("-"," ")}`:`${district.name} · ${core.districtCompletion(district.id)}% complete`;
  $("#sewerHud").classList.toggle("hidden",!sewerActive);$("#sewerSection").textContent=Config.SEWER_SECTIONS.find(section=>section.id===state.sewer.player.section)?.name||"Fruitopia Sewers";$("#sewerWaterCount").textContent=state.sewer.samples.filter(sample=>!sample.consumed).length;$("#clubChipCount").textContent=state.sewer.mafia.clubChips;
  const event=Config.EVENTS.find(item=>item.id===state.event.active);$("#weatherIcon").textContent=event?.icon||"☀️";$("#eventName").textContent=event?.name||"Bright Morning";$("#eventTimer").textContent=event?`${remaining(state.event.endsAt)}s remaining`:"No active event";
}
function renderQuestSide(){core.checkQuestProgress();$("#questList").innerHTML=core.state.quests.slice(0,3).map(quest=>`<div class="quest-row"><span class="quest-icon">${quest.icon}</span><div><strong>${escapeHtml(quest.name)}</strong><small>${Math.floor(quest.progress||0)} / ${quest.target}</small><div class="progress"><i style="width:${clamp((quest.progress||0)/quest.target*100,0,100)}%"></i></div></div>${quest.claimed?"<small>DONE</small>":(quest.progress||0)>=quest.target?`<button class="claim" data-do="claim-quest" data-id="${quest.id}">Claim</button>`:""}</div>`).join("");}
function renderRequestSide(){let order=core.state.phone.orders.find(item=>item.status==="offered"||item.status==="accepted");if(!order)order=core.generateOrder();const name=order.kind==="fruit"?fruitName(order.item):productName(order.item),icon=order.kind==="fruit"?Config.FRUIT_BY_ID[order.item]?.icon:Config.RECIPE_BY_ID[order.item]?.icon;$("#customerRequest").innerHTML=`<div class="request-main"><span class="customer-avatar">${icon||"🧺"}</span><div><strong>${escapeHtml(order.customer)}</strong><small>${order.status==="offered"?"New order":"Accepted order"} · ${money(order.payment)}</small></div></div><div class="request-items">${order.quantity}× ${escapeHtml(name)}${order.kind==="fruit"?` · ${Config.QUALITY_NAMES[order.quality]}`:""}</div><div class="request-actions">${order.status==="offered"?`<button data-do="order-negotiate" data-id="${order.id}" data-value="accept">Accept</button><button data-nav="phone" data-page="orders">Negotiate</button>`:`<button data-do="supply-order" data-id="${order.id}">Supply order</button>`}</div>`;}
function renderCoach(){const stats=core.state.stats;let title="Pick your first apple",text="Walk to a glowing tree and harvest it. Manual picking can uncover Fruit Coins and better-quality fruit.";if(stats.harvested>0&&!stats.sold){title="Sell from your basket";text="Open the Fruit Book and sell an apple, or let the roadside stand make an automatic sale.";}else if(stats.sold>0&&!stats.improvements){title="Improve Sunny Side";text="Open Company, choose Districts, and build the Better Sign to grow customer traffic.";}else if(stats.improvements&&!stats.crafted){title="Grow beyond raw fruit";text="Unlock fruit, craft a recipe, and start building your product warehouse.";}else if(stats.crafted){title="Build the fruit empire";text="Complete districts, hire specialists, automate deliveries, research hybrids, and prepare for a new season.";}$("#coachTitle").textContent=title;$("#coachText").textContent=text;}

function statStrip(items){return `<div class="stat-strip">${items.map(([label,value])=>`<div class="stat-box"><small>${label}</small><strong>${value}</strong></div>`).join("")}</div>`;}
function openPage(page,sub=null,replacing=false){currentView={page,sub};const renderers={office:renderOffice,company:renderCompany,recipes:renderRecipes,deliveries:renderDeliveries,phone:renderPhone,arcade:renderArcade,fruitbook:renderFruitBook,season:renderSeason,more:renderMore,map:renderMap,district:renderDistrict,worker:renderWorker,applicant:renderApplicant,tree:renderTree,sewer:renderSewer,manhole:renderManhole,"sewer-object":renderSewerObject,"mafia-game":renderMafiaGame};const view=renderers[page]?.(sub);if(!view)return;if(replacing&&minigame){minigame.destroy();minigame=null;}openDialog(view.title,view.icon,view.body,{kicker:view.kicker,className:view.className});afterRender(page,sub);}
function afterRender(page,sub){if(page==="office"&&(sub||"overview")==="overview")positionOfficePlayer();if(page==="arcade"&&sub?.startsWith("play:")){const gameId=sub.slice(5),started=core.startMinigame(gameId);if(!started.ok){feedback(started);return openPage("arcade");}const stage=$("#minigameMount");minigame=new MiniGameController(stage,core,started.run,{onFinish:()=>{updateUI();save();}});}if(page==="company"&&(sub||"districts")==="buildings")bindBuildingFilters();if(page==="sewer"&&sub==="club"){const ball=$(".plinko-ball[data-slot]");if(ball)requestAnimationFrame(()=>ball.classList.add("dropping"));}}

function renderOffice(sub="overview"){
  sub=sub||"overview";const state=core.state,nav=tabs([["overview","Walkable office"],["upgrades","44 upgrades"],["workers","Team"],["recruiting","Recruiting"]],sub);let content="";
  if(sub==="overview"){
    const stage=Config.OFFICE_LEVELS[state.office.level-1],objects=Config.OFFICE_OBJECTS.map((object,index)=>{const owned=index<5||state.office.upgrades.some(upgrade=>upgrade.includes(object.id.split("-")[0]))||state.office.level>=Math.ceil((index+1)/4);return `<button class="office-object" data-do="office-object" data-id="${object.id}" ${owned?"":`disabled title="Upgrade the office to unlock ${object.name}"`} style="left:${5+(index%5)*19}%;top:${10+Math.floor(index/5)*24}%"><span>${object.icon}</span><small>${escapeHtml(object.name)}</small></button>`;}).join("");
    const waiting=state.workerRequests.filter(request=>request.status==="waiting");
    content=`${statStrip([["Office stage",`${state.office.level}/5`],["Safe",money(state.office.safe)],["Visitors",waiting.length],["Team",Object.keys(state.workers).length],["Upgrades",`${state.office.upgrades.length}/44`]])}<div class="section-head"><div><h3>${stage}</h3><p>Walk with WASD, arrows, or click an object. Every available object opens a working company system.</p></div></div><div id="officeRoom" class="office-room" tabindex="0">${objects}<div id="officePlayer" class="office-player">🧑‍💼</div><aside class="office-visitors"><strong>Waiting room</strong><br>${waiting.length?waiting.map(request=>escapeHtml(Config.WORKER_BY_ID[request.workerId]?.name||request.workerId)).join("<br>"):"No queued visits — your door is open."}</aside></div>${waiting.length?`<h3>Worker office visits</h3><div class="card-grid">${waiting.map(request=>{const worker=Config.WORKER_BY_ID[request.workerId];return `<article class="game-card"><span class="big-icon">${worker.avatar}</span><h3>${escapeHtml(worker.name)}</h3><p>Wants to discuss ${escapeHtml(request.type.replace("-"," "))}. Your decision affects happiness, loyalty, skills, Cash, and memories.</p><div class="button-row"><button data-do="worker-visit" data-id="${request.id}" data-value="support">Support request</button><button data-do="worker-visit" data-id="${request.id}" data-value="delay">Ask to wait</button></div></article>`;}).join("")}</div>`:""}`;
  }else if(sub==="upgrades")content=`<div class="section-head"><div><h3>Office improvement plan</h3><p>Communication, finance, people, technology, marketing, and office upgrades turn the shed into a command center.</p></div></div><div class="card-grid four">${Config.OFFICE_UPGRADES.map(upgrade=>{const owned=state.office.upgrades.includes(upgrade.id),locked=state.level<upgrade.level;return `<article class="game-card ${locked?"locked":""}"><span class="big-icon">${({Communication:"☎️",Finance:"🧮",Workers:"👥",Technology:"💻",Marketing:"📣",Office:"🏢"})[upgrade.category]}</span><h3>${escapeHtml(upgrade.name)}</h3><div class="tag-row"><span class="tag">${upgrade.category}</span><span class="tag">Level ${upgrade.level}</span></div><p>${escapeHtml(upgrade.description)}</p><button data-do="office-upgrade" data-id="${upgrade.id}" ${owned||locked?"disabled":""}>${owned?"Installed":locked?`Unlocks at level ${upgrade.level}`:`Install · ${money(upgrade.cashCost)}${upgrade.coinCost?` + ${upgrade.coinCost} 🪙`:""}`}</button></article>`;}).join("")}</div>`;
  else if(sub==="workers")content=renderWorkerRoster();
  else content=renderRecruiting();
  return{title:"The Fruitopia Office",icon:"🏡",body:nav+`<div class="dialog-body">${content}</div>`};
}
function positionOfficePlayer(){const player=$("#officePlayer");if(!player)return;player.style.left=`${core.state.office.player.x}%`;player.style.top=`${core.state.office.player.y}%`;}
function renderWorkerRoster(){const entries=Object.values(core.state.workers);return `<div class="section-head"><div><h3>${entries.length} company worker${entries.length===1?"":"s"}</h3><p>Assign, train, equip, rest, promote, and build lasting relationships with every worker.</p></div></div><div class="card-grid">${entries.map(employee=>{const worker=Config.WORKER_BY_ID[employee.workerId];return `<article class="game-card worker-card"><span class="worker-avatar">${worker.avatar}</span><div><header><h3>${escapeHtml(worker.name)}</h3><span class="tag gold">${employee.rank}</span></header><small>${escapeHtml(worker.role)} · ${escapeHtml(employee.assignment)}</small><div class="meter-label"><span>Happiness</span><b>${Math.round(employee.happiness)}%</b></div><div class="mini-meter"><i style="width:${employee.happiness}%"></i></div><div class="meter-label"><span>Energy</span><b>${Math.round(employee.energy)}%</b></div><div class="mini-meter"><i style="width:${employee.energy}%;background:#54b8da"></i></div><button data-nav="worker" data-id="${worker.id}">Manage & talk</button></div></article>`;}).join("")}</div>`;}
function renderRecruiting(){const applicants=Object.values(core.state.applicants),active=applicants.filter(item=>!["hired","rejected","prospect"].includes(item.status));return `<section class="notice"><strong>Fictional hiring only.</strong> Fruitopia applicants, references, salaries, and employment records never leave this local game.</section><div class="section-head"><div><h3>Hiring Center</h3><p>Recruit through advertisements, applications, interviews, reference checks, trial shifts, and negotiated offers.</p></div><button class="primary-button" style="width:auto" data-do="create-job-ad">Create job advertisement</button></div>${statStrip([["Applications",active.length],["Shortlisted",applicants.filter(a=>a.status==="shortlisted").length],["Interviews",applicants.filter(a=>a.status==="interview").length],["Trial shifts",applicants.filter(a=>a.status==="trial").length],["Hired",Object.keys(core.state.workers).length]])}<div class="card-grid">${applicants.map(applicant=>{const worker=Config.WORKER_BY_ID[applicant.workerId];return `<article class="game-card ${applicant.status==="prospect"?"locked":""}"><span class="big-icon">${worker.avatar}</span><header><h3>${escapeHtml(worker.name)}</h3><span class="tag ${applicant.status==="hired"?"gold":""}">${escapeHtml(applicant.status)}</span></header><p>${escapeHtml(worker.personalStatement)}</p><div class="tag-row"><span class="tag">${escapeHtml(worker.role)}</span><span class="tag">${escapeHtml(worker.preferredSchedule)}</span></div><button data-nav="applicant" data-id="${worker.id}" ${applicant.status==="prospect"?"disabled":""}>${applicant.status==="prospect"?"Needs recruiting campaign":"Open application"}</button></article>`;}).join("")}</div>`;}

function renderWorker(workerId){const worker=Config.WORKER_BY_ID[workerId],employee=core.state.workers[workerId];if(!worker||!employee)return renderOffice("workers");const districts=Config.DISTRICTS.filter(d=>core.state.districts[d.id].unlocked);return{title:worker.name,icon:worker.avatar,className:"narrow",body:`<div class="dialog-body">${statStrip([["Rank",employee.rank],["Skill",employee.skill],["Equipment",employee.equipment],["Loyalty",`${Math.round(employee.loyalty)}%`],["Energy",`${Math.round(employee.energy)}%`]])}<div class="game-card"><h3>${escapeHtml(worker.role)}</h3><p>${escapeHtml(worker.personality)}. Favorite fruit: ${escapeHtml(worker.favoriteFruit)}.</p><div class="inventory-line"><span>Strength</span><strong>${escapeHtml(worker.strength)}</strong></div><div class="inventory-line"><span>Weakness</span><strong>${escapeHtml(worker.weakness)}</strong></div><div class="inventory-line"><span>Special ability</span><strong>${escapeHtml(worker.specialAbility)}</strong></div></div><label>District assignment<select id="workerAssignment" class="field" style="width:100%">${districts.map(d=>`<option ${employee.assignment===d.name?"selected":""}>${escapeHtml(d.name)}</option>`).join("")}<option ${employee.assignment==="Office"?"selected":""}>Office</option></select></label><div class="button-row" style="margin-top:10px"><button class="primary-button" data-do="worker-action" data-id="${worker.id}" data-value="assign">Assign</button><button class="secondary-button" data-do="worker-action" data-id="${worker.id}" data-value="talk">Talk</button></div><div class="button-row" style="margin-top:7px"><button class="secondary-button" data-do="worker-action" data-id="${worker.id}" data-value="train">Train</button><button class="secondary-button" data-do="worker-action" data-id="${worker.id}" data-value="equipment">Buy equipment</button><button class="secondary-button" data-do="worker-action" data-id="${worker.id}" data-value="rest">Rest</button><button class="secondary-button" data-do="worker-action" data-id="${worker.id}" data-value="promote">Promote</button></div><h3>Memories</h3><div class="notice">${employee.memories.map(memory=>`• ${escapeHtml(memory)}`).join("<br>")}</div><h3>Dialogue history</h3><div class="notice">${employee.dialogue.length?employee.dialogue.map(line=>escapeHtml(line)).join("<br>"):"No conversations yet."}</div></div>`};}

function renderApplicant(workerId){const worker=Config.WORKER_BY_ID[workerId],applicant=core.state.applicants[workerId];if(!worker||!applicant)return renderOffice("recruiting");const interview=applicant.interview;return{title:`Application · ${worker.name}`,icon:worker.avatar,body:`<div class="dialog-body">${statStrip([["Status",applicant.status],["Experience",`${worker.experience} years`],["Salary",`${money(worker.expectedSalary)}/day`],["Schedule",worker.preferredSchedule],["Relationship",applicant.relationship]])}<div class="card-grid two"><article class="game-card"><h3>Application file</h3><div class="inventory-line"><span>Desired position</span><strong>${escapeHtml(worker.role)}</strong></div><div class="inventory-line"><span>Training</span><strong>${escapeHtml(worker.education)}</strong></div><div class="inventory-line"><span>Strongest skill</span><strong>${applicant.information>=25?escapeHtml(worker.strength):"Ask to learn"}</strong></div><div class="inventory-line"><span>Weakest skill</span><strong>${applicant.information>=50?escapeHtml(worker.weakness):"Not yet revealed"}</strong></div><div class="inventory-line"><span>Special ability</span><strong>${applicant.information>=75?escapeHtml(worker.specialAbility):"Hidden"}</strong></div><p>${escapeHtml(worker.personalStatement)}</p><label>Hiring notes<textarea id="hiringNotes" class="field" rows="3" style="width:100%">${escapeHtml(applicant.notes)}</textarea></label></article><article class="game-card"><h3>Applicant conversation</h3><p>Introduce yourself, ask about their work, explain Fruitopia, offer a tour, or request a reference.</p><div class="button-row"><button data-do="applicant" data-id="${worker.id}" data-value="info">Ask for information</button><button data-do="applicant" data-id="${worker.id}" data-value="reference">Check reference</button></div><div class="button-row"><button data-do="applicant" data-id="${worker.id}" data-value="shortlist">Shortlist</button><button data-do="applicant" data-id="${worker.id}" data-value="interview">Schedule interview</button><button data-do="applicant" data-id="${worker.id}" data-value="reject">Reject politely</button></div></article></div>${applicant.status==="interview"?`<h3>Office interview</h3>${statStrip([["Comfort",`${interview.comfort}%`],["Information",`${interview.information}%`],["Suitability",`${interview.suitability}%`],["Professionalism",`${interview.professionalism}%`],["Interest",`${interview.interest}%`]])}<div class="notice">${escapeHtml(worker.name)} walks in, sits down, greets you, and notices your ${Config.OFFICE_LEVELS[core.state.office.level-1].toLowerCase()}.</div><div class="button-row" style="margin-top:8px"><button class="secondary-button" data-do="interview-answer" data-id="${worker.id}" data-value="professional">Ask about experience</button><button class="secondary-button" data-do="interview-answer" data-id="${worker.id}" data-value="friendly">Ask about teamwork</button><button class="secondary-button" data-do="interview-answer" data-id="${worker.id}" data-value="humorous">Ask their favorite fruit</button></div>`:""}${["interviewed","shortlisted"].includes(applicant.status)?`<button class="primary-button" style="margin-top:12px" data-do="applicant" data-id="${worker.id}" data-value="trial">Offer trial shift</button>`:""}${["trial","interviewed","counteroffer"].includes(applicant.status)?`<h3>Job offer</h3><div class="card-grid two"><label>Starting salary<input id="offerSalary" class="field" type="number" min="1" value="${applicant.offer?.counterSalary||worker.expectedSalary}"></label><label>Position<select id="offerPosition" class="field">${Config.JOB_ROLES.map(role=>`<option ${role===worker.role?"selected":""}>${escapeHtml(role)}</option>`).join("")}</select></label></div><button class="primary-button" style="margin-top:10px" data-do="applicant" data-id="${worker.id}" data-value="offer">Send complete offer</button>`:""}</div>`};}

function renderCompany(sub="districts"){
  sub=sub||"districts";const nav=tabs([["districts","8 districts"],["buildings","106 buildings"],["labs","Fruit labs"]],sub);let content="";
  if(sub==="districts")content=`${statStrip([["Districts",`${Config.DISTRICTS.filter(d=>core.state.districts[d.id].unlocked).length}/8`],["Improvements",`${core.state.stats.improvements}/64`],["Buildings",`${Object.keys(core.state.buildings).length}/106`],["Reputation",Math.round(core.state.reputation)],["Lifetime Cash",money(core.state.lifetimeCash)]])}<div class="card-grid">${Config.DISTRICTS.map(district=>{const data=core.state.districts[district.id],pct=core.districtCompletion(district.id),locked=!data.unlocked;return `<article class="game-card ${locked?"locked":""}"><header><span class="big-icon">${locked?"🔒":district.icon}</span><span class="completion-ring" style="--pct:${pct}%" data-label="${pct}%"></span></header><h3>${escapeHtml(district.name)}</h3><p>${escapeHtml(district.summary)}.</p><div class="tag-row"><span class="tag">Level ${district.unlockLevel}</span><span class="tag">${data.upgrades.length}/8 improvements</span>${data.teleporter?"<span class='tag purple'>Teleporter</span>":""}</div><button data-nav="district" data-id="${district.id}">${locked?core.districtLockReason(district):"Enter district"}</button></article>`;}).join("")}</div>`;
  else if(sub==="buildings")content=`<div class="section-head"><div><h3>Company Construction</h3><p>Every building has three operating levels, four visual states, a district home, and a live company effect.</p></div><div><select id="buildingCategory" aria-label="Building category" class="field"><option value="all">All 106 buildings</option>${[...new Set(Config.BUILDINGS.map(b=>b.category))].map(category=>`<option>${category}</option>`).join("")}</select> <input id="buildingSearch" class="field" placeholder="Search buildings" aria-label="Search buildings"></div></div><div id="buildingGrid" class="card-grid four">${renderBuildingCards(Config.BUILDINGS)}</div>`;
  else content=`<div class="section-head"><div><h3>Interactive fruit laboratories</h3><p>Construct a lab, discover a specialty fruit, then run studies that improve the lowest-quality relevant fruit without exceeding Golden quality.</p></div></div><div class="card-grid two">${Config.LABS.map(lab=>{const owned=core.state.buildings[lab.id];return `<article class="game-card"><span class="big-icon">🔬</span><header><h3>${escapeHtml(lab.name)}</h3><span class="tag">${owned?`Level ${owned.level}`:"Not built"}</span></header><p>${lab.specialties.map(id=>`${Config.FRUIT_BY_ID[id]?.icon||"❔"} ${fruitName(id)}`).join(" · ")}</p><div class="inventory-line"><span>Studies completed</span><strong>${core.state.studies[lab.id]?.length||0}</strong></div><button data-do="lab-study" data-id="${lab.id}" ${owned?"":"disabled"}>${owned?`Run study · ${money(lab.cashCost)} + ${lab.researchCost} RP`:`Construct ${lab.name} in Buildings`}</button></article>`;}).join("")}</div>`;
  return{title:"Fruitopia Company",icon:"🏗️",body:nav+`<div class="dialog-body">${content}</div>`};
}
function renderBuildingCards(buildings){return buildings.map(building=>{const owned=core.state.buildings[building.id],locked=core.state.level<building.unlockLevel||!core.state.districts[building.district]?.unlocked;return `<article class="game-card ${locked?"locked":""}" data-building-card data-category="${building.category}" data-name="${building.name.toLowerCase()}"><span class="big-icon">${building.icon}</span><header><h3>${escapeHtml(building.name)}</h3><span class="tag">${escapeHtml(building.category)}</span></header><p>${escapeHtml(building.description)}</p><div class="tag-row"><span class="tag">Level ${building.unlockLevel}</span><span class="tag purple">${escapeHtml(building.effect.type)}</span><span class="tag">${escapeHtml(Config.DISTRICT_BY_ID[building.district].name)}</span></div><button data-do="${owned?"upgrade-building":"build-building"}" data-id="${building.id}" ${(!owned&&locked)||owned?.level>=3?"disabled":""}>${owned?owned.level>=3?"Fruitopia landmark":`Upgrade to level ${owned.level+1} · ${money(building.cashCost*(owned.level+1))}`:locked?`Requires level ${building.unlockLevel} + district`:`Build · ${money(building.cashCost)}${building.coinCost?` + ${building.coinCost} 🪙`:""}`}</button></article>`;}).join("");}
function bindBuildingFilters(){const category=$("#buildingCategory"),search=$("#buildingSearch");if(!category||!search)return;const filter=()=>{$$("[data-building-card]").forEach(card=>{const matchCategory=category.value==="all"||card.dataset.category===category.value,matchName=card.dataset.name.includes(search.value.toLowerCase());card.classList.toggle("hidden",!matchCategory||!matchName);});};category.addEventListener("change",filter);search.addEventListener("input",filter);}

function renderDistrict(districtId){const district=Config.DISTRICT_BY_ID[districtId],data=core.state.districts[districtId];if(!district||!data)return renderCompany();const cards=district.upgrades.map((name,index)=>{const owned=data.upgrades.includes(index),available=data.unlocked&&(index===0||data.upgrades.includes(index-1)),cost=core.districtUpgradeCost(districtId,index);return `<article class="game-card ${!available&&!owned?"locked":""}"><span class="big-icon">${owned?"✅":district.icon}</span><header><h3>${index+1}. ${escapeHtml(name)}</h3><span class="tag">${(index+1)*12.5}%</span></header><p>Improves ${escapeHtml(district.summary)}.</p><button data-do="district-upgrade" data-id="${district.id}" data-index="${index}" ${owned||!available?"disabled":""}>${owned?"Completed":available?`Build · ${money(cost.cash)}${cost.coins?` + ${cost.coins} 🪙`:""}`:`Complete ${escapeHtml(district.upgrades[index-1]||"the prior step")}`}</button></article>`;}).join("");return{title:district.name,icon:district.icon,body:`<div class="dialog-body">${statStrip([["Completion",`${core.districtCompletion(district.id)}%`],["Improvements",`${data.upgrades.length}/8`],["Hidden crate",data.crateFound?"Found":"Somewhere nearby"],["Teleporter",data.teleporter?"Online":"75% required"],["Minigame",Config.MINIGAMES.find(g=>g.id===district.minigame)?.name]])}<div class="button-row"><button class="secondary-button" data-do="collect-crate" data-id="${district.id}" ${data.crateFound||!data.unlocked?"disabled":""}>${data.crateFound?"Crate collected":"Search hidden Fruit Coin crate"}</button><button class="secondary-button" data-do="teleport" data-id="${district.id}" ${data.teleporter?"":"disabled"}>${data.teleporter?"Teleport here":"Teleporter activates at 75%"}</button><button class="secondary-button" data-do="start-minigame" data-id="${district.minigame}">Play ${Config.MINIGAMES.find(g=>g.id===district.minigame)?.name}</button></div><div class="card-grid four" style="margin-top:12px">${cards}</div></div>`};}

function renderRecipes(sub="craft"){
  sub=sub||"craft";const nav=tabs([["craft","21 recipes"],["production","10 production lines"]],sub);let content="";
  if(sub==="craft")content=`${statStrip([["Recipes",`${Config.RECIPES.filter(r=>core.state.level>=r.unlockLevel).length}/21`],["Basket",`${total(core.state.fruitInventory)}/${core.state.basketCapacity}`],["Warehouse",`${total(core.state.productInventory)}/${core.state.warehouseCapacity}`],["Crafted",core.state.stats.crafted],["Featured",productName(core.state.featured.id)]])}<div class="card-grid">${Config.RECIPES.map(recipe=>{const locked=core.state.level<recipe.unlockLevel,missing=core.ingredientsMissing(recipe.ingredients);return `<article class="game-card ${locked?"locked":""}"><span class="big-icon">${recipe.icon}</span><header><h3>${escapeHtml(recipe.name)}</h3><strong>${money(recipe.value)}</strong></header><p>Uses ${escapeHtml(formatItems(recipe.ingredients))}. Premium automatic sale value.</p><div class="inventory-line"><span>Stored products</span><strong>${core.state.productInventory[recipe.id]||0}</strong></div><button data-do="craft" data-id="${recipe.id}" ${locked||missing.length?"disabled":""}>${locked?`Unlocks at level ${recipe.unlockLevel}`:missing.length?`Missing ${escapeHtml(missing.join(", "))}`:"Craft one"}</button>${core.state.productInventory[recipe.id]?`<div class="button-row" style="margin-top:6px"><button data-do="sell-product" data-id="${recipe.id}">Sell one</button><button data-do="feature" data-kind="product" data-id="${recipe.id}">Feature +40%</button></div>`:""}</article>`;}).join("")}</div>`;
  else content=`<div class="section-head"><div><h3>Timed production businesses</h3><p>Jobs consume inventory when queued, complete while offline, and can be collected exactly once.</p></div></div>${core.state.production.length?`<h3>Production queue</h3><div class="card-grid">${core.state.production.filter(job=>!job.collected).map(job=>`<article class="game-card"><span class="big-icon">⚙️</span><h3>${escapeHtml(productName(job.recipe))}</h3><div class="timer-line"><span>Status</span><strong>${job.readyAt<=Date.now()?"Ready":`${remaining(job.readyAt)}s`}</strong></div><button data-do="collect-production" data-id="${job.id}" ${job.readyAt>Date.now()?"disabled":""}>${job.readyAt<=Date.now()?"Collect batch":"Production running"}</button></article>`).join("")}</div>`:""}<h3>Production lines</h3><div class="card-grid two">${Config.PRODUCTION_LINES.map(line=>{const owned=core.state.buildings[line.building],recipe=Config.RECIPE_BY_ID[line.recipe],missing=core.ingredientsMissing(recipe.ingredients);return `<article class="game-card ${owned?"":"locked"}"><span class="big-icon">🏭</span><header><h3>${escapeHtml(line.name)}</h3><span class="tag">${recipe.icon} ${escapeHtml(recipe.name)}</span></header><p>Timed ${recipe.seconds}s batch. Ingredients: ${escapeHtml(formatItems(recipe.ingredients))}.</p><button data-do="start-production" data-id="${line.id}" ${!owned||missing.length?"disabled":""}>${!owned?`Construct ${escapeHtml(line.name)} first`:missing.length?`Missing ${escapeHtml(missing.join(", "))}`:"Start one-item batch"}</button></article>`;}).join("")}</div>`;
  return{title:"Recipes & Production",icon:"🥤",body:nav+`<div class="dialog-body">${content}</div>`};
}

function renderDeliveries(sub="routes"){
  sub=sub||"routes";const nav=tabs([["routes","18 routes"],["fleet","Fleet garage"],["active","Active deliveries"]],sub),state=core.state;let content="";
  if(sub==="routes")content=`${statStrip([["Service tier",`${state.serviceTier}/7`],["Tier name",Config.DELIVERY_TIERS[state.serviceTier-1]],["Reputation",state.deliveryReputation],["Subscribers",state.deliverySubscribers],["Streak",state.deliveryStreak]])}<div class="notice"><strong>Automatic delivery only.</strong> Prepare cargo, select a route, and dispatch a capable vehicle. You never have to drive to customer houses.</div><div class="card-grid" style="margin-top:12px">${Config.ROUTES.map(route=>{const vehicle=Config.VEHICLE_BY_ID[route.vehicle],owned=state.vehicles[route.vehicle],missing=core.routeMissing(route),locked=state.serviceTier<route.tier;return `<article class="game-card ${locked?"locked":""}"><span class="big-icon">${vehicle.icon}</span><header><h3>${escapeHtml(route.name)}</h3><strong>${money(route.payment)}</strong></header><p>Fruit: ${escapeHtml(formatItems(route.fruit))}. Products: ${escapeHtml(formatItems(route.products,"product"))}.</p><div class="tag-row"><span class="tag">Tier ${route.tier}</span><span class="tag">${route.xp} XP</span>${route.subscription?"<span class='tag purple'>Subscription</span>":""}</div><button data-do="dispatch" data-id="${route.id}" ${locked||!owned||owned.busy||missing.length?"disabled":""}>${locked?`Need service tier ${route.tier}`:!owned?`Buy ${vehicle.name}`:owned.busy?"Vehicle busy":missing.length?`Missing ${escapeHtml(missing.join(", "))}`:`Dispatch ${vehicle.name}`}</button></article>`;}).join("")}</div>`;
  else if(sub==="fleet")content=`<div class="section-head"><div><h3>Fleet garage</h3><p>Vehicles have rising capability, route compatibility, purchase requirements, and safe available/busy states.</p></div></div><div class="card-grid four">${Config.VEHICLES.map(vehicle=>{const owned=state.vehicles[vehicle.id],locked=state.level<vehicle.unlockLevel;return `<article class="game-card ${locked?"locked":""}"><span class="big-icon">${vehicle.icon}</span><h3>${escapeHtml(vehicle.name)}</h3><div class="tag-row"><span class="tag">Capability ${vehicle.capability}</span><span class="tag">Level ${vehicle.unlockLevel}</span></div><p>Speed ${vehicle.speed.toFixed(1)} · compatible with routes requiring ${vehicle.name}.</p><button data-do="buy-vehicle" data-id="${vehicle.id}" ${owned||locked?"disabled":""}>${owned?owned.busy?"Busy on route":"Available in garage":locked?`Unlocks at level ${vehicle.unlockLevel}`:`Buy · ${money(vehicle.cashCost)}${vehicle.coinCost?` + ${vehicle.coinCost} 🪙`:""}`}</button></article>`;}).join("")}</div>`;
  else content=`<div class="section-head"><div><h3>Delivery tracker</h3><p>Travel continues while Fruitopia is closed. Every contract is paid exactly once when its vehicle returns.</p></div></div>${state.activeDeliveries.filter(d=>!d.paid).length?`<div class="card-grid">${state.activeDeliveries.filter(d=>!d.paid).map(delivery=>{const route=Config.ROUTES.find(r=>r.id===delivery.routeId),vehicle=Config.VEHICLE_BY_ID[delivery.vehicleId];return `<article class="game-card"><span class="big-icon">${vehicle.icon}</span><h3>${escapeHtml(route.name)}</h3><div class="timer-line"><span>Return</span><strong>${remaining(delivery.readyAt)}s</strong></div><button data-do="complete-delivery" data-id="${delivery.id}" ${delivery.readyAt>Date.now()?"disabled":""}>${delivery.readyAt<=Date.now()?"Process return":"Traveling automatically"}</button></article>`;}).join("")}</div>`:`<div class="empty-state">No vehicles are traveling. Prepare cargo and dispatch a route.</div>`}`;
  return{title:"Fruitopia Delivery Service",icon:"🚚",body:nav+`<div class="dialog-body">${content}</div>`};
}

function renderPhone(app="messages"){
  if(!core.state.phone.unlocked)return{title:"Fruitopia Smartphone",icon:"📱",className:"narrow",body:`<div class="dialog-body"><div class="empty-state"><h3>📵 Smartphone locked</h3><p>Install <strong>Basic Desk Phone</strong> and then <strong>Fruitopia Smartphone</strong> from Office Upgrades.</p><button class="primary-button" data-do="go-office-upgrades">Open Office Upgrades</button></div></div>`};
  app=app||"messages";const buttons=Config.PHONE_APPS.map(item=>`<button class="${item.id===app?"active":""}" data-do="phone-app" data-value="${item.id}"><span>${item.icon}</span>${item.name}</button>`).join("");return{title:"Fruitopia Smartphone",icon:"📱",body:`<div class="phone-shell"><aside class="phone-apps"><h3>Apps</h3><div class="app-grid">${buttons}</div></aside><section class="phone-content">${renderPhoneApp(app)}</section></div>`};
}
function renderPhoneApp(app){const state=core.state.phone;if(app==="messages")return `<div class="section-head"><div><h3>Messages</h3><p>Workers, customers, events, payments, and mysterious callers send actionable updates.</p></div></div>${state.messages.map(message=>`<article class="message-row ${message.unread?"unread":""}"><header><strong>${escapeHtml(message.from)}</strong><small>${escapeHtml(message.subject)}</small></header><p>${escapeHtml(message.body)}</p>${message.paymentId?`<button class="primary-button" data-do="collect-payment" data-id="${message.paymentId}">Collect payment</button>`:""}${message.responses?.length&&!message.response?`<div class="message-actions">${message.responses.map(response=>`<button data-do="respond-message" data-id="${message.id}" data-value="${escapeHtml(response)}">${escapeHtml(response)}</button>`).join("")}</div>`:message.response?`<small>Replied: ${escapeHtml(message.response)}</small>`:""}</article>`).join("")}`;
  if(app==="contacts"){const sewerContacts=Object.values(state.contacts||{});return `<h3>Fruitopia Contacts</h3>${Config.CONTACTS.map(contact=>`<article class="message-row"><strong>${escapeHtml(contact)}</strong><p>${contact==="Unknown Orchard"?"Locked contact · follow clues in Secrets.":"Available for fictional company conversations and requests."}</p><button class="secondary-button" data-do="contact-message" data-value="${contact}">Send company greeting</button></article>`).join("")}${sewerContacts.length?`<h3>Discovered Sewer Contacts</h3>${sewerContacts.map(contact=>`<article class="message-row"><strong>${escapeHtml(contact.name)}</strong><p>${escapeHtml(contact.role)} · remembers your underground conversations.</p><button class="secondary-button" data-do="contact-message" data-value="${escapeHtml(contact.name)}">Send sewer follow-up</button></article>`).join("")}`:""}`;}
  if(app==="orders")return `<div class="section-head"><div><h3>Customer Orders</h3><p>Negotiate, supply from real inventory, and collect each fictional payment once.</p></div><button class="primary-button" style="width:auto" data-do="generate-order">Request new order</button></div>${state.orders.map(order=>`<article class="message-row"><header><strong>${escapeHtml(order.customer)}</strong><span class="tag">${order.status}</span></header><p>${order.quantity}× ${escapeHtml(order.kind==="fruit"?fruitName(order.item):productName(order.item))} · ${money(order.payment)}</p>${order.status==="offered"?`<div class="message-actions">${[["accept","Accept"],["more-10","Ask 10% more"],["more-25","Ask 25% more"],["premium","Offer premium"],["faster","Faster delivery"],["more-time","Request time"],["decline","Decline politely"]].map(([value,label])=>`<button data-do="order-negotiate" data-id="${order.id}" data-value="${value}">${label}</button>`).join("")}</div>`:order.status==="accepted"?`<button class="primary-button" data-do="supply-order" data-id="${order.id}">Supply now</button>`:""}</article>`).join("")}`;
  if(app==="workers")return renderWorkerRoster();if(app==="delivery-tracker")return renderDeliveries("active").body.replace(/<nav[\s\S]*?<\/nav>/,"");
  if(app==="fruit-market")return `<h3>Today's fictional Fruit Market</h3><div class="notice"><strong>Market stalls:</strong> ${core.state.marketStalls.map((slot,index)=>`#${index+1} ${slot?(slot.type==="fruit"?fruitName(slot.id):productName(slot.id)):"empty"}`).join(" · ")}${core.state.marketStalls.every(Boolean)?" · Three-item combo bonus active!":""}</div><div class="card-grid two" style="margin-top:10px">${Config.FRUITS.filter(f=>core.state.discoveredFruit[f.id]).map((fruit,index)=>{const price=Math.max(1,Math.round(fruit.baseValue*(.8+(index%5)*.1)));return `<article class="game-card"><header><h3>${fruit.icon} ${fruit.name}</h3><strong>${money(price)}</strong></header><p>Demand ${fruit.demand}/5 · stored ${core.state.fruitInventory[fruit.id]||0}</p><div class="button-row"><button data-do="sell-fruit" data-id="${fruit.id}">Sell one</button><button data-do="buy-market-fruit" data-id="${fruit.id}" data-price="${price}">Buy one</button><button data-do="market-stall" data-kind="fruit" data-id="${fruit.id}">Assign stall</button></div></article>`;}).join("")}</div>`;
  if(app==="company-bank")return `<section class="notice"><strong>Fictional in-game funds only.</strong> No real money, bank account, cryptocurrency, or real investment is involved.</section><div class="card-grid" style="margin-top:12px">${Config.COMPANY_FUNDS.map(fund=>`<article class="game-card"><span class="big-icon">🏦</span><h3>${escapeHtml(fund.name)}</h3><p>Timed fictional dividend ${(fund.rate*100).toFixed(0)}% · no real-world value.</p><button data-do="invest" data-id="${fund.id}">Invest $25 in-game Cash</button></article>`).join("")}</div><h3>Investments</h3>${state.investments.map(item=>`<article class="message-row"><strong>${escapeHtml(Config.COMPANY_FUNDS.find(f=>f.id===item.fundId)?.name)}</strong><p>${money(item.returnAmount)} · ${item.readyAt<=Date.now()?"ready":`${remaining(item.readyAt)}s`}</p><button data-do="collect-investment" data-id="${item.id}" ${item.readyAt>Date.now()||item.collected?"disabled":""}>${item.collected?"Collected":"Collect dividend"}</button></article>`).join("")}`;
  const routes={quests:["more","quests"],achievements:["more","achievements"],research:["more","research"],"world-map":["map",null],settings:["more","settings"],secrets:["more","secrets"]};if(routes[app])return `<div class="empty-state"><h3>${Config.PHONE_APPS.find(item=>item.id===app)?.icon} ${Config.PHONE_APPS.find(item=>item.id===app)?.name}</h3><p>This app opens the complete matching company screen.</p><button class="primary-button" data-do="route-page" data-value="${routes[app][0]}" data-sub="${routes[app][1]||""}">Open app</button></div>`;return `<div class="empty-state">This app is ready.</div>`;}

function renderArcade(sub=null){if(sub?.startsWith("play:")){const game=Config.MINIGAMES.find(item=>item.id===sub.slice(5));return{title:game.name,icon:game.icon,body:`<div class="dialog-body"><div id="minigameMount"></div><button class="secondary-button" style="margin-top:8px" data-do="end-minigame">End run and score now</button></div>`};}return{title:"Fruitopia Arcade",icon:"🎮",body:`<div class="dialog-body">${statStrip([["Playable games","11"],["Runs",core.state.minigames.runs],["Tickets",core.state.tickets],["Best score",core.state.stats.highScore],["Mastery",`${Object.keys(core.state.minigames.highScores).length}/11`]])}<div class="notice">Every game is timed, score-based, pointer/touch/keyboard accessible, replayable, and rewards each completed run exactly once.</div><div class="card-grid" style="margin-top:12px">${Config.MINIGAMES.map(game=>{const score=core.state.minigames.highScores[game.id]||0,locked=core.state.level<game.unlockLevel;return `<article class="game-card ${locked?"locked":""}"><span class="big-icon">${game.icon}</span><header><h3>${escapeHtml(game.name)}</h3><span class="tag gold">High ${score}</span></header><small>${escapeHtml(game.location)}</small><p>${escapeHtml(game.description)}</p><button data-do="start-minigame" data-id="${game.id}" ${locked?"disabled":""}>${locked?`Unlocks at level ${game.unlockLevel}`:`Play${game.cost?` · ${game.cost} 🪙 unlock`:""}`}</button></article>`;}).join("")}</div></div>`};}

function renderFruitBook(){return{title:"Fruit Book & Inventory",icon:"📖",body:`<div class="dialog-body">${statStrip([["Discovered",`${Object.values(core.state.discoveredFruit).filter(Boolean).length}/28`],["Basket",`${total(core.state.fruitInventory)}/${core.state.basketCapacity}`],["Products",`${total(core.state.productInventory)}/${core.state.warehouseCapacity}`],["Patents",`${core.state.patents.length}/11`],["Fruit quality","5 grades"]])}<div class="card-grid four">${Config.FRUITS.map(fruit=>{const discovered=core.state.discoveredFruit[fruit.id],quality=Config.QUALITY_NAMES[core.state.fruitQuality[fruit.id]||0],quantity=core.state.fruitInventory[fruit.id]||0,uses=Config.RECIPES.filter(recipe=>recipe.ingredients[fruit.id]).map(recipe=>recipe.name);return `<article class="game-card ${discovered?"":"locked"}"><span class="big-icon">${discovered?fruit.icon:"❔"}</span><header><h3>${discovered?escapeHtml(fruit.name):"Unknown fruit"}</h3><span class="tag ${fruit.rarity==="Cosmic"?"purple":""}">${discovered?fruit.rarity:"Locked"}</span></header><p>${discovered?`${fruit.source}. Uses: ${uses.join(", ")||"Research and sales"}.`: `Unlock at level ${fruit.unlockLevel}, through research, or district progress.`}</p><div class="inventory-line"><span>Quantity</span><strong>${discovered?quantity:"—"}</strong></div><div class="inventory-line"><span>Quality</span><strong class="quality">${discovered?quality:"—"}</strong></div><div class="inventory-line"><span>Base value</span><strong>${discovered?money(fruit.baseValue):"—"}</strong></div>${discovered&&quantity?`<div class="button-row"><button data-do="sell-fruit" data-id="${fruit.id}">Sell one</button><button data-do="feature" data-kind="fruit" data-id="${fruit.id}">Feature +40%</button></div>`:""}</article>`;}).join("")}</div><h3>Crafted warehouse</h3><div class="card-grid four">${Config.RECIPES.filter(recipe=>(core.state.productInventory[recipe.id]||0)>0).map(recipe=>`<article class="game-card"><span class="big-icon">${recipe.icon}</span><h3>${escapeHtml(recipe.name)}</h3><strong>${core.state.productInventory[recipe.id]} stored</strong><button data-do="sell-product" data-id="${recipe.id}">Sell one · ${money(recipe.value)}</button></article>`).join("")||"<div class='empty-state'>Crafted products appear here separately from fresh fruit.</div>"}</div></div>`};}

function renderSeason(){const ready=core.canBeginSeason();return{title:"Seasonal Legacy",icon:"🌱",body:`<div class="dialog-body">${statStrip([["Season",core.state.season],["Evolution age",Config.EVOLUTION_AGES[core.state.evolutionAge]],["Golden Seeds",core.state.goldenSeeds],["Lifetime Cash",money(core.state.lifetimeCash)],["Ready",ready?"Yes":"Level 18 / $250k"]])}<section class="notice danger"><strong>New Season resets ordinary progress.</strong> Cash, districts, ordinary upgrades, inventory, production, and fleet reset. Golden Seeds, permanent bonuses, settings, achievements, high scores, fruit discoveries, research notebook, worker memories/loyalty, decorations, and evolution age remain.</section><button class="danger-button" style="margin:12px 0" data-do="season-confirm" ${ready?"":"disabled"}>${ready?"Begin a new season…":"Reach level 18 or $250,000 lifetime Cash"}</button><h3>Permanent Golden Seed upgrades</h3><div class="card-grid">${Config.GOLDEN_SEED_UPGRADES.map(upgrade=>{const level=core.state.permanent[upgrade.id]||0,cost=level+1;return `<article class="game-card"><span class="big-icon">🌟</span><header><h3>${escapeHtml(upgrade.name)}</h3><span class="tag gold">Level ${level}</span></header><p>${escapeHtml(upgrade.description)} Costs rise each level.</p><button data-do="buy-permanent" data-id="${upgrade.id}">Upgrade · ${cost} Golden Seed${cost===1?"":"s"}</button></article>`;}).join("")}</div></div>`};}

function renderMore(sub="progress"){
  sub=sub||"progress";const nav=tabs([["progress","Progress"],["quests","Quests"],["research","Research"],["achievements","Achievements"],["secrets","Secrets"],["events","Events"],["sewer","Sewers"],["settings","Settings"]],sub);let content="";
  if(sub==="progress")content=`${statStrip([["Empire level",core.state.level],["Title",levelTitle(core.state.level)],["Research",`${core.state.researchPoints} RP`],["Tickets",core.state.tickets],["Completed contracts",core.state.completedContracts]])}<div class="card-grid two"><article class="game-card"><h3>Central company loop</h3><p>1. Pick fruit. 2. Sell or craft. 3. Earn resources. 4. Build. 5. Unlock. 6. Automate. 7. Interact for bonuses. 8. Begin a new season.</p></article><article class="game-card"><h3>Tracked company values</h3><p>Cash, Fruit Coins, XP, reputation, happiness, loyalty, energy, quality, delivery reputation, subscribers, streak, contracts, tickets, high scores, lifetime Cash, Golden Seeds, seasons, evolution age, achievements, secrets, patents, and relationships.</p></article></div>`;
  else if(sub==="quests")content=`<h3>Daily quests</h3><div class="card-grid">${core.state.quests.map(quest=>`<article class="game-card"><span class="big-icon">${quest.icon}</span><h3>${escapeHtml(quest.name)}</h3><div class="progress"><i style="width:${clamp((quest.progress||0)/quest.target*100,0,100)}%"></i></div><p>${quest.progress||0} / ${quest.target}</p><button data-do="claim-quest" data-id="${quest.id}" ${quest.claimed||(quest.progress||0)<quest.target?"disabled":""}>${quest.claimed?"Claimed":`Claim reward`}</button></article>`).join("")}</div><h3>Milestones</h3><div class="card-grid four">${Config.MILESTONES.map(milestone=>{const done=core.state.milestones[milestone.id],progress=core.state.stats[milestone.stat]||0;return `<article class="game-card"><h3>${escapeHtml(milestone.name)}</h3><p>${escapeHtml(milestone.description)} · ${progress}/${milestone.target}</p><button data-do="claim-milestone" data-id="${milestone.id}" ${done||progress<milestone.target?"disabled":""}>${done?"Claimed":`Claim ${milestone.reward} 🪙`}</button></article>`;}).join("")}</div>`;
  else if(sub==="research")content=renderResearch();
  else if(sub==="achievements")content=`<div class="card-grid">${Config.ACHIEVEMENTS.map(achievement=>{const earned=core.state.achievements[achievement.id],progress=core.state.stats[achievement.stat]||0;return `<article class="game-card ${earned?"":"locked"}"><span class="big-icon">🏆</span><h3>${escapeHtml(achievement.name)}</h3><p>${achievement.stat}: ${progress} / ${achievement.target}</p><strong>${earned?`Earned · ${achievement.reward} Fruit Coins awarded once`:`Reward ${achievement.reward} Fruit Coins`}</strong></article>`;}).join("")}</div>`;
  else if(sub==="secrets")content=`<div class="notice">Unknown mysteries become investigations through worker stories, messages, research, furniture, events, buildings, weather, exploration, and minigame mastery.</div><div class="card-grid" style="margin-top:12px">${Config.SECRETS.map(secret=>{const progress=core.state.secrets[secret.id];return `<article class="game-card ${progress.discovered?"":"locked"}"><span class="big-icon">${progress.discovered?"🔓":"🔐"}</span><h3>${progress.clues?escapeHtml(secret.name):"Unknown secret"}</h3><p>${progress.clues?escapeHtml(secret.clue):"Search for a clue to reveal this mystery."}</p><div class="tag-row"><span class="tag">${progress.clues}/3 clues</span>${progress.discovered?"<span class='tag gold'>Discovered</span>":""}</div><div class="button-row"><button data-do="secret" data-id="${secret.id}" data-value="clue" ${progress.discovered?"disabled":""}>Search · ${secret.researchCost} RP</button><button data-do="secret" data-id="${secret.id}" data-value="investigate" ${progress.discovered||progress.clues<2?"disabled":""}>Investigate · ${money(secret.cashCost)}</button></div></article>`;}).join("")}</div>`;
  else if(sub==="events")content=`<div class="section-head"><div><h3>Economy-changing events</h3><p>Events create timers, world effects, phone updates, and operational opportunities.</p></div></div><div class="card-grid four">${Config.EVENTS.map(event=>`<article class="game-card"><span class="big-icon">${event.icon}</span><h3>${escapeHtml(event.name)}</h3><p>Affects ${escapeHtml(event.effect)} for ${event.duration} seconds.</p><button data-do="start-event" data-id="${event.id}" ${core.state.event.active?"disabled":""}>${core.state.event.active?"Another event is active":"Start demo event"}</button></article>`).join("")}</div>`;
  else if(sub==="sewer")content=`<div class="section-head"><div><h3>Underground Fruitopia</h3><p>Track special inventory, experiments, maze progress, sewer quests, and the silly fictional Fruit Mafia Club.</p></div></div>${statStrip([["Open manholes",Object.values(core.state.sewer.entrances).filter(item=>item.open).length],["Samples",core.state.sewer.samples.filter(sample=>!sample.consumed).length],["Recipes",Object.keys(core.state.sewer.lab.recipes).length],["Club Chips",core.state.sewer.mafia.clubChips],["Membership",core.state.sewer.mafia.membership?"Permanent":"Locked"]])}<button class="primary-button" data-nav="sewer">Open Sewer Headquarters</button>`;
  else content=`<div class="card-grid two">${[["sound","Sound effects","Purchase, coin, harvest, success, failure, level-up, countdown, and minigame feedback."],["music","Gentle background music","A quiet optional musical pulse."],["reducedMotion","Reduced motion","Stops decorative motion and shortens animated movement."],["autosave","Autosave","Saves local versioned progress every ten seconds."]].map(([id,name,description])=>`<article class="game-card"><span class="big-icon">⚙️</span><h3>${name}</h3><p>${description}</p><button data-do="setting" data-id="${id}">${core.state.settings[id]?"On":"Off"} · toggle</button></article>`).join("")}</div><button class="danger-button" style="margin-top:20px" data-do="reset-save-confirm">Reset local save…</button>`;
  return{title:"More Fruitopia",icon:"☰",body:nav+`<div class="dialog-body">${content}</div>`};
}
function renderResearch(){const active=core.state.researchJobs.filter(job=>!job.resolved);return `${statStrip([["Research Points",core.state.researchPoints],["Patents",`${core.state.patents.length}/11`],["Discoveries",Object.values(core.state.discoveredFruit).filter(Boolean).length],["Studies",core.state.stats.studies],["Active",active.length]])}${active.length?`<h3>Research queue</h3><div class="card-grid">${active.map(job=>`<article class="game-card"><span class="big-icon">🧪</span><h3>${escapeHtml(fruitName(job.result))}</h3><p>${job.readyAt<=Date.now()?"Experiment ready to record.":`${remaining(job.readyAt)} seconds remaining. Continues offline.`}</p><button data-do="resolve-research" data-id="${job.id}" ${job.readyAt>Date.now()?"disabled":""}>${job.readyAt<=Date.now()?"Record result":"Researching"}</button></article>`).join("")}</div>`:""}<h3>Hybrid Research Board</h3><div class="card-grid">${Config.HYBRIDS.map(hybrid=>{const discovered=core.state.patents.includes(hybrid.result),parentsKnown=hybrid.parents.every(id=>core.state.discoveredFruit[id]);return `<article class="game-card ${parentsKnown?"":"locked"}"><span class="big-icon">${Config.FRUIT_BY_ID[hybrid.result].icon}</span><h3>${discovered?escapeHtml(fruitName(hybrid.result)):"Unknown hybrid"}</h3><p>${hybrid.parents.map(id=>`${Config.FRUIT_BY_ID[id].icon} ${fruitName(id)}`).join(" + ")} · costs 2 of each and ${hybrid.researchCost} RP.</p><button data-do="hybrid" data-id="${hybrid.id}" ${discovered||!parentsKnown?"disabled":""}>${discovered?"Discovered & patented":parentsKnown?"Begin experiment":"Discover both parent fruits"}</button></article>`;}).join("")}</div>`;}

function renderMap(){return{title:"Fruitopia World Map",icon:"🗺️",body:`<div class="dialog-body"><div class="section-head"><div><h3>District teleport network</h3><p>Teleporters activate at 75% district completion. You can always close the map and walk or pan there manually.</p></div></div><div class="card-grid four">${Config.DISTRICTS.map(district=>{const data=core.state.districts[district.id];return `<article class="game-card ${data.unlocked?"":"locked"}"><span class="big-icon">${data.unlocked?district.icon:"🔒"}</span><h3>${escapeHtml(district.name)}</h3><p>${core.districtCompletion(district.id)}% complete.</p><button data-do="teleport" data-id="${district.id}" ${data.teleporter?"":"disabled"}>${data.teleporter?"Teleport":"Complete 75% to activate"}</button></article>`;}).join("")}</div></div>`};}

function sewerTabs(active){return tabs([["overview","Sewer overview"],["inventory","Inventory"],["notebook","Experiment notebook"],["lab","Test Lab"],["maze","Maze progress"],["quests","Sewer quests"],["secrets","Sewer secrets"],["club","Fruit Mafia Club"]],active);}
function sewerItemName(id){return Config.SEWER_ITEM_BY_ID[id]?.name||id.replaceAll("-"," ");}
function renderManhole(entranceId){const entrance=Config.SEWER_ENTRANCE_BY_ID[entranceId],progress=core.state.sewer.entrances[entranceId];if(!entrance||!progress)return renderSewer();return{title:entrance.name,icon:progress.open?"🪜":"🕳️",className:"narrow",kicker:"FRUITOPIA ROADWORKS",body:`<div class="dialog-body"><div class="manhole-illustration ${progress.open?"open":""}" aria-hidden="true"><span class="cover">◉</span><span class="glow"></span><span class="ladder">╫<br>╫<br>╫</span></div><h3>${progress.open?"The cover is open":"It almost looks like ordinary roadwork"}</h3><p>${escapeHtml(entrance.unlock)}</p><div class="tag-row"><span class="tag">${progress.discovered?"Discovered":"Uninspected"}</span><span class="tag">${progress.open?"Open forever":"Locked"}</span><span class="tag">Accessible label: Open manhole</span></div><div class="button-row"><button class="secondary-button" data-do="manhole" data-id="${entrance.id}" data-value="inspect">Inspect cover</button><button class="secondary-button" data-do="manhole" data-id="${entrance.id}" data-value="listen">Listen through it</button></div><div class="button-row" style="margin-top:7px"><button class="secondary-button" data-do="manhole" data-id="${entrance.id}" data-value="symbol">Read strange symbol</button><button class="primary-button" data-do="manhole" data-id="${entrance.id}" data-value="open" ${progress.open?"disabled":""}>${progress.open?"Cover already open":"Try to open"}</button></div>${progress.open?`<button class="primary-button sewer-enter" data-do="enter-sewer" data-id="${entrance.id}">Enter Sewer</button>`:""}</div>`};}

function renderSewer(sub="overview"){
  sub=sub||"overview";const sewer=core.state.sewer,nav=sewerTabs(sub);let content="";
  if(sub==="overview")content=`${statStrip([["Location",sewer.active?Config.SEWER_SECTIONS.find(section=>section.id===sewer.player.section)?.name||"Sewer":"Surface"],["Entrances",`${Object.values(sewer.entrances).filter(item=>item.open).length}/6`],["Water samples",sewer.samples.filter(sample=>!sample.consumed).length],["Recipes",`${Object.keys(sewer.lab.recipes).length}/8`],["Maze gates",`${Object.values(sewer.maze.gates).filter(Boolean).length}/4`]])}<section class="notice sewer-notice"><strong>Mysterious, drippy, and strictly family-friendly.</strong> The Fruit Mafia is a silly fictional fruit club. Club Chips and every machine prize exist only inside Fruitopia and have no real-world value.</section><div class="card-grid two" style="margin-top:12px">${Config.SEWER_SECTIONS.map(section=>`<article class="game-card sewer-card"><span class="big-icon">${({"drainage-entrance":"🪜","green-water-channels":"💚","sewer-test-lab":"🧪","sewer-maze":"🧭","fruit-mafia-club":"🍇"})[section.id]}</span><h3>${section.name}</h3><p>${section.description}</p><span class="tag">${sewer.player.section===section.id&&sewer.active?"Current section":section.id==="fruit-mafia-club"&&!sewer.mafia.membership?"Hidden behind the maze":"Explorable"}</span></article>`).join("")}</div><div class="button-row" style="margin-top:12px">${sewer.active?`<button class="primary-button" data-do="find-sewer-player">Find me underground</button><button class="secondary-button" data-do="leave-sewer">Return to Surface</button>`:`<button class="secondary-button" data-action="close-dialog">Close and find a road manhole</button>`}</div>`;
  else if(sub==="inventory"){
    const items=Object.entries(sewer.inventory).filter(([,amount])=>amount>0),samples=sewer.samples.filter(sample=>!sample.consumed);
    content=`${statStrip([["Containers",Config.SEWER_CONTAINERS.reduce((sum,item)=>sum+(sewer.inventory[item.id]||0),0)],["Filled samples",samples.length],["Club Chips",sewer.mafia.clubChips],["Keys",(sewer.inventory["valve-key"]||0)+(sewer.inventory["maintenance-key"]||0)],["Navigation aids",(sewer.inventory["chalk-marker"]||0)+(sewer.inventory["maze-note"]||0)+(sewer.inventory["emergency-return-token"]||0)]])}<h3>Sewer Inventory</h3><div class="card-grid four">${items.map(([itemId,amount])=>{const item=Config.SEWER_ITEM_BY_ID[itemId];return `<article class="game-card"><span class="big-icon">${item?.icon||"📦"}</span><h3>${escapeHtml(item?.name||itemId)}</h3><strong>${amount} stored</strong></article>`;}).join("")||"<div class='empty-state'>Inspect and open the first manhole to receive a basic bottle.</div>"}</div><h3>Filled Green Water samples</h3><div class="card-grid">${samples.map(sample=>`<article class="game-card"><span class="big-icon">💧</span><h3>${escapeHtml(sample.quality)}</h3><p>${escapeHtml(Config.SEWER_CONTAINER_BY_ID[sample.containerId]?.name)} · collected at ${new Date(sample.collectedAt).toLocaleTimeString()}</p><span class="tag">Ready for the Test Lab</span></article>`).join("")||"<div class='empty-state'>Collect water at a glowing sewer channel using an available container.</div>"}</div>${sewer.active&&sewer.inventory["emergency-return-token"]?`<button class="secondary-button" data-do="use-return-token">Use one Emergency Return Token</button>`:""}`;
  }else if(sub==="notebook")content=`<div class="section-head"><div><h3>Sewer Experiment Notebook</h3><p>Unknown combinations remain question marks until discovered through experiments, dialogue, maze notes, or messages.</p></div></div><div class="card-grid two">${Config.SEWER_RECIPES.map(recipe=>{const known=sewer.lab.recipes[recipe.id];return `<article class="game-card ${known?"":"locked"}"><span class="big-icon">${known?Config.SEWER_ITEM_BY_ID[recipe.result]?.icon||"🧪":"❔"}</span><h3>${known?escapeHtml(recipe.name):"Unknown sewer recipe"}</h3><p>${known?`${recipe.water==="any-green"?"Green Sewer Water":sewerItemName(recipe.water)} + ${fruitName(recipe.ingredient)!==recipe.ingredient?fruitName(recipe.ingredient):sewerItemName(recipe.ingredient)}. ${recipe.effect}`:"Experiment, talk to sewer characters, and inspect maintenance clues."}</p><span class="tag">${known?`Discovered · ${known.experiments} run${known.experiments===1?"":"s"}`:"? + ?"}</span></article>`;}).join("")}</div><h3>Experiment history</h3>${sewer.lab.history.map(item=>`<article class="message-row"><strong>${item.success?"Successful mixture":"Useful failed mixture"}</strong><p>${escapeHtml(sewerItemName(item.result))} · ${new Date(item.startedAt).toLocaleTimeString()} · collected once</p></article>`).join("")||"<div class='empty-state'>Completed underground experiments will be recorded here.</div>"}`;
  else if(sub==="lab")content=renderSewerLab();
  else if(sub==="maze")content=renderSewerMaze();
  else if(sub==="quests")content=`<div class="section-head"><div><h3>Sewer Quests</h3><p>Explore, repair, experiment, and help odd underground neighbors.</p></div></div><div class="card-grid">${Config.SEWER_QUESTS.map(quest=>{const progress=sewer.quests[quest.id];return `<article class="game-card ${progress.completed?"":"locked"}"><span class="big-icon">${progress.claimed?"✅":progress.completed?"🎁":"📌"}</span><h3>${escapeHtml(quest.name)}</h3><p>${escapeHtml(quest.description)}</p><button data-do="claim-sewer-quest" data-id="${quest.id}" ${!progress.completed||progress.claimed?"disabled":""}>${progress.claimed?"Reward claimed":progress.completed?"Claim sewer reward":"Explore to complete"}</button></article>`;}).join("")}</div>`;
  else if(sub==="secrets")content=`<section class="notice"><strong>Underground clues stay mysterious.</strong> Graffiti, worker dialogue, laboratory notes, messages, maze symbols, prize tickets, and hidden rooms reveal these discoveries.</section><div class="card-grid" style="margin-top:12px">${Config.SEWER_SECRETS.map(secret=>{const progress=sewer.secrets[secret.id];return `<article class="game-card ${progress.discovered?"":"locked"}"><span class="big-icon">${progress.discovered?"🔓":"❔"}</span><h3>${progress.clues?escapeHtml(secret.name):"Unknown sewer secret"}</h3><p>${progress.discovered?"Discovery recorded permanently in the sewer notebook.":progress.clues?`${progress.clues}/${secret.clueTarget} clues found.`:"No reliable clue yet."}</p><div class="button-row"><button data-do="sewer-secret" data-id="${secret.id}" data-value="clue" ${progress.discovered?"disabled":""}>Search · 2 RP</button><button data-do="sewer-secret" data-id="${secret.id}" data-value="investigate" ${progress.discovered||progress.clues<secret.clueTarget?"disabled":""}>Investigate · $50</button></div></article>`;}).join("")}</div>`;
  else content=renderMafiaClubWithMystery();
  return{title:"Fruitopia Sewers",icon:"🕳️",kicker:"UNDER FRUITOPIA",body:nav+`<div class="dialog-body sewer-dialog">${content}</div>`};
}

function renderSewerLab(){const sewer=core.state.sewer,experiment=sewer.lab.activeExperiment,samples=sewer.samples.filter(sample=>!sample.consumed),fruitOptions=Config.FRUITS.filter(fruit=>(core.state.fruitInventory[fruit.id]||0)>0),specialOptions=["rare-seed","strange-mushroom","research-sample"].filter(id=>(sewer.inventory[id]||0)>0);return experiment?`<div class="sewer-machine active"><div class="machine-lights"><i></i><i></i><i></i></div><div class="machine-slots"><span>💧 ${escapeHtml(experiment.sample.quality)}</span><span>${Config.FRUIT_BY_ID[experiment.ingredient]?.icon||Config.SEWER_ITEM_BY_ID[experiment.ingredient]?.icon||"🧪"} ${escapeHtml(fruitName(experiment.ingredient)!==experiment.ingredient?fruitName(experiment.ingredient):sewerItemName(experiment.ingredient))}</span><span>${experiment.additional?escapeHtml(sewerItemName(experiment.additional)):"No extra"}</span></div><div class="bubbling-chamber" aria-label="Experiment bubbling">🫧🧪🫧</div><h3>${experiment.readyAt<=Date.now()?"Result chamber ready":`${remaining(experiment.readyAt)} seconds remaining`}</h3><p>Intensity: ${escapeHtml(experiment.intensity)} · ${experiment.purified?"purified mixture":"unpurified mixture"}. The result continues safely while Fruitopia is closed.</p><button class="primary-button" data-do="collect-sewer-experiment" data-id="${experiment.id}" ${experiment.readyAt>Date.now()?"disabled":""}>${experiment.readyAt<=Date.now()?"Collect result once":"Experiment bubbling"}</button></div>`:`<div class="section-head"><div><h3>Experimental Mixing Machine</h3><p>Choose one filled sample and a real inventory ingredient. Inputs are deducted atomically when the timer starts.</p></div></div>${!sewer.lab.discovered?"<section class='notice danger'>Walk to the Sewer Test Lab and inspect its mixing machine first.</section>":""}<div class="sewer-machine"><div class="machine-lights"><i></i><i></i><i></i></div><div class="card-grid two"><label>Water sample<select id="sewerSample" class="field">${samples.map(sample=>`<option value="${sample.id}">${escapeHtml(sample.quality)} · ${escapeHtml(Config.SEWER_CONTAINER_BY_ID[sample.containerId]?.name)}</option>`).join("")||"<option value=''>No filled samples</option>"}</select></label><label>Fruit or ingredient<select id="sewerIngredient" class="field">${[...fruitOptions.map(fruit=>`<option value="${fruit.id}">${fruit.icon} ${fruit.name} (${core.state.fruitInventory[fruit.id]})</option>`),...specialOptions.map(id=>`<option value="${id}">${Config.SEWER_ITEM_BY_ID[id].icon} ${Config.SEWER_ITEM_BY_ID[id].name} (${sewer.inventory[id]})</option>`)].join("")||"<option value=''>No usable ingredient</option>"}</select></label><label>Additional ingredient<select id="sewerAdditional" class="field"><option value="">None</option>${specialOptions.map(id=>`<option value="${id}">${Config.SEWER_ITEM_BY_ID[id].name}</option>`).join("")}</select></label><label>Intensity<select id="sewerIntensity" class="field"><option value="gentle">Gentle · safest</option><option value="normal" selected>Normal · balanced</option><option value="wild">Wild · faster, less reliable</option></select></label><label>Duration<select id="sewerDuration" class="field"><option value="quick">Quick</option><option value="standard" selected>Standard</option><option value="careful">Careful</option></select></label><label class="check-field"><input id="sewerPurify" type="checkbox"> Purify mixture · 2 RP</label></div><button class="primary-button" data-do="start-sewer-experiment" ${!sewer.lab.discovered||!samples.length||(!fruitOptions.length&&!specialOptions.length)?"disabled":""}>Start bubbling experiment</button></div>`;}

function renderSewerMaze(){const maze=core.state.sewer.maze,atMap=core.canViewMazeMap();return `${statStrip([["Map studied",maze.mapStudied?"Yes":"Not yet"],["Valves",`${Object.values(maze.valves).filter(Boolean).length}/5`],["Gates",`${Object.values(maze.gates).filter(Boolean).length}/4`],["Shortcuts",`${Object.values(maze.shortcuts).filter(Boolean).length}/3`],["Treasures",`${Object.values(maze.treasures).filter(Boolean).length}/5`]])}<section class="notice ${atMap?"":"danger"}"><strong>${atMap?"You are standing at the entrance map.":"Complete map unavailable here."}</strong> ${atMap?"Study it as long as you like before entering.":"Return to the front entrance. The phone map and this progress screen never reveal the maze layout."}</section>${atMap?`<button class="primary-button" style="margin-top:10px" data-nav="sewer-object" data-id="sewer-map:entrance-map">Open complete entrance map</button>`:""}<h3>Remembered landmarks</h3><div class="tag-row">${["Red pipe","Blue pipe","Yellow valve","Broken fruit sign","Giant apple graffiti","Glowing mushroom","Maintenance cart","Old laboratory door","Waterfall pipe","Fruit Mafia symbol"].map(label=>`<span class="tag">${escapeHtml(label)}</span>`).join("")}</div><h3>Limited navigation assistance</h3><div class="card-grid">${[["chalk-marker","Chalk markers","Leave a temporary breadcrumb trail without revealing the map.",10],["maze-note","Direction notes","Keep one written landmark reminder.",15],["emergency-return-token","Emergency return token","Return safely to the entrance once.",25]].map(([id,name,description,cost])=>`<article class="game-card"><span class="big-icon">${Config.SEWER_ITEM_BY_ID[id].icon}</span><h3>${name}</h3><p>${description}</p><button data-do="buy-sewer-aid" data-id="${id}">Buy · ${money(cost)}</button></article>`).join("")}</div>`;}

function renderMafiaClub(){const sewer=core.state.sewer,mafia=sewer.mafia,plinko=sewer.plinko,slots=sewer.slots;if(!mafia.membership)return `<section class="notice"><strong>Silly fictional fruit club.</strong> No violence, real money, real gambling, purchases, or cash-out exists here.</section><div class="club-door"><span>🍇</span><h3>Big Fig's Velvet Rope</h3><p>${mafia.invitation?"Your invitation is valid. The $100 payment is a one-time permanent membership fee; all return visits are free.":"Find the Fruit Mafia symbol and earn an invitation in the maze first."}</p><button class="secondary-button" data-do="mafia-ask">Ask about the club</button><button class="primary-button" data-do="mafia-membership" ${mafia.invitation?"":"disabled"}>${mafia.invitation?"Pay $100 and enter permanently":"Invitation required"}</button></div>`;
  const pending=plinko.pending,spin=slots.pending;return `${statStrip([["Membership","Permanent"],["Club Chips",mafia.clubChips],["Mafia reputation",mafia.reputation],["Plinko today",`${plinko.playsToday}/${Config.PLINKO_DAILY_LIMIT}`],["Slots today",`${slots.playsToday}/${Config.SLOT_DAILY_LIMIT}`]])}<section class="notice"><strong>Fictional Club Chips only.</strong> Chips cannot be bought with, exchanged for, or redeemed as real money. Posted daily limits prevent unlimited rapid play.</section><div class="club-room"><article class="club-machine"><header><div><small>FRUIT-BALL MACHINE</small><h3>🍎 Fruit Plinko</h3></div><strong>${pending?pending.free?"FREE DROP":`${pending.cost} CHIPS`:`${Config.PLINKO_COST} CHIPS`}</strong></header><p>The wide middle jackpot is deliberately favored at approximately 28%, but never guaranteed. Your first drop each Fruitopia day is free.</p><div class="plinko-board" aria-label="Seven-slot Fruit Plinko board"><div class="plinko-pegs">•　•　•　•<br>　•　•　•<br>•　•　•　•<br>　•　•　•</div>${pending?`<div class="plinko-ball" data-slot="${pending.visualSlot}" style="--slot:${pending.visualSlot}">🍒</div>`:""}<div class="plinko-slots">${Config.PLINKO_SLOTS.map((slot,index)=>`<span class="${slot.jackpot?"jackpot":""}" data-plinko-slot="${index}">${slot.jackpot?"JACKPOT":slot.chips+" 🟣"}</span>`).join("")}</div></div>${pending?`<button class="primary-button" data-do="collect-plinko" data-id="${pending.id}" ${pending.readyAt>Date.now()?"disabled":""}>${pending.readyAt<=Date.now()?`Collect ${escapeHtml(pending.label)}`:"Ball bouncing…"}</button>`:`<label>Drop position<select id="plinkoPosition" class="field"><option value="0">Far left</option><option value="1">Left</option><option value="2">Center-left</option><option value="3" selected>Center</option><option value="4">Center-right</option><option value="5">Right</option><option value="6">Far right</option></select></label><button class="primary-button" data-do="plinko-drop">Drop fruit ball</button>`}<details><summary>Posted prize table</summary><p>Edges: 1 chip · medium: 3 chips · large: 5 chips · center jackpot: 10 chips plus $50 Cash, 1 Fruit Coin, 2 RP, and a ticket.</p></details></article><article class="club-machine"><header><div><small>FAMILY-FRIENDLY REELS</small><h3>🎰 Fruit Slot Machine</h3></div><strong>${Config.SLOT_COST} CHIPS</strong></header><p>Approximate rarity: two matching fruit are occasional; three fruit are uncommon; three Golden Apples, Rainbow Fruit, or Mafia grapes are rare. Maximum ${Config.SLOT_DAILY_LIMIT} spins daily.</p><div class="slot-reels" data-reels="${spin?escapeHtml(spin.visualReels.join("")):""}">${(spin?.visualReels||["🍎","🍋","🍌"]).map(symbol=>`<span class="${spin?"spinning":""}">${symbol}</span>`).join("")}</div>${spin?`<p class="slot-result">${spin.readyAt<=Date.now()?escapeHtml(spin.label):"Reels spinning…"}</p><button class="primary-button" data-do="collect-slots" data-id="${spin.id}" ${spin.readyAt>Date.now()?"disabled":""}>${spin.readyAt<=Date.now()?"Collect result once":"Spinning…"}</button>`:`<button class="primary-button" data-do="spin-slots">Spin three reels</button>`}<details><summary>Posted prize table</summary><p>Two match: 3 chips · three normal: 7 · Golden Apples: 12 · Rainbow Fruit: 16 · Mafia grapes: 20. A non-match awards nothing.</p></details></article></div><section class="private-room"><span>🚪</span><div><h3>Private game room — rules coming later.</h3><p>Configuration and safe save support are prepared. This future challenge is locked, inaccessible, and is not counted among the 11 playable minigames.</p></div></section><div class="card-grid two"><article class="game-card"><h3>Recent Plinko results</h3><p>${plinko.history.slice(0,5).map(run=>`${escapeHtml(run.label)} · +${run.rewardChips} chips`).join("<br>")||"No completed drops yet."}</p></article><article class="game-card"><h3>Recent fruit reels</h3><p>${slots.history.slice(0,5).map(run=>`${run.reels.join(" ")} · ${escapeHtml(run.label)}`).join("<br>")||"No completed spins yet."}</p></article></div>`;}

function renderSewerObject(key){const [type,id]=String(key||"").split(":");if(type==="sewer-map"){const allowed=core.canViewMazeMap();return{title:"Sewer Maze Entrance Map",icon:"🗺️",kicker:"ENTRANCE VIEW ONLY",body:`<div class="dialog-body">${allowed?`<div class="maze-map" role="img" aria-label="Rough sewer maze map showing entrance, intersections, colored pipe landmarks, laboratory, exits, locked gates, and a mysterious unmarked east section"><span class="map-lab">🧪 TEST LAB</span><span class="map-entry">📍 YOU ARE HERE</span><span class="map-red">🔴 RED PIPE</span><span class="map-blue">🔵 BLUE PIPE</span><span class="map-yellow">🟡 YELLOW VALVE</span><span class="map-gate">🚧 LOCKED GRATES</span><span class="map-exit">🪜 EXITS</span><span class="map-mystery">? UNMARKED</span></div><p>The map deliberately omits treasure positions and exact puzzle solutions. Once you walk away, this complete view closes and cannot be reopened from the phone.</p><button class="primary-button" data-do="study-maze-map">Study and remember landmarks</button>`:`<section class="notice danger"><strong>Map unavailable.</strong> Stand beside the large map at the front entrance. The phone map does not reveal the sewer maze.</section>`}</div>`};}
  if(type==="water-point"){const point=Config.WATER_POINT_BY_ID[id],progress=core.state.sewer.collectionPoints[id],ready=progress.readyAt<=Date.now();return{title:point.name,icon:"💧",className:"narrow",kicker:"GREEN-WATER COLLECTION",body:`<div class="dialog-body"><span class="water-orb" aria-hidden="true">💧</span><h3>${point.quality}</h3><p>${ready?"Select an available container and fill it. Filled containers travel safely to the Sewer Test Lab.":`${remaining(progress.readyAt)} seconds until this source respawns.`}</p><label>Container<select id="waterContainer" class="field" style="width:100%">${Config.SEWER_CONTAINERS.filter(container=>(core.state.sewer.inventory[container.id]||0)>0).map(container=>`<option value="${container.id}">${container.icon} ${container.name} · owned ${core.state.sewer.inventory[container.id]}</option>`).join("")||"<option value=''>No container owned</option>"}</select></label><button class="primary-button" style="margin-top:10px" data-do="collect-green-water" data-id="${id}" ${!ready?"disabled":""}>${ready?"Collect Green Water":"Water source refilling"}</button></div>`};}
  if(type==="sewer-lab")return renderSewer("lab");if(type==="plinko"||type==="fruit-slots")return renderSewer("club");if(type==="future-mafia-game")return renderMafiaGame();
  if(type==="sewer-exit")return{title:"Return to Surface",icon:"🪜",className:"narrow",body:`<div class="dialog-body"><p>The ladder returns to ${escapeHtml(Config.SEWER_ENTRANCE_BY_ID[id]?.name||"Fruitopia")}. Sewer progress, shortcuts, experiments, membership, and discoveries remain saved.</p><button class="primary-button" data-do="leave-sewer">Climb to Surface</button></div>`};
  if(type==="sewer-valve"){const item=Config.SEWER_VALVES.find(value=>value.id===id),on=core.state.sewer.maze.valves[id];return{title:item.name,icon:"🛞",className:"narrow",body:`<div class="dialog-body"><p>${item.effect}</p><button class="primary-button" data-do="turn-sewer-valve" data-id="${id}" ${on?"disabled":""}>${on?"Valve position saved":"Turn valve"}</button></div>`};}
  if(type==="sewer-gate"){const item=Config.SEWER_GATES.find(value=>value.id===id),open=core.state.sewer.maze.gates[id];return{title:item.name,icon:open?"🟢":"🚧",className:"narrow",body:`<div class="dialog-body"><p>${open?"This grate is permanently open in your save.":item.hint}</p><button class="primary-button" data-do="unlock-sewer-gate" data-id="${id}" ${open?"disabled":""}>${open?"Gate open":"Try requirement"}</button></div>`};}
  if(type==="sewer-shortcut"){const item=Config.SEWER_SHORTCUTS.find(value=>value.id===id),open=core.state.sewer.maze.shortcuts[id];return{title:item.name,icon:open?"🚪":"🔒",className:"narrow",body:`<div class="dialog-body"><p>Once repaired, this route stays open in the versioned save.</p><button class="primary-button" data-do="open-sewer-shortcut" data-id="${id}" ${open?"disabled":""}>${open?"Shortcut open":"Repair shortcut"}</button></div>`};}
  if(type==="sewer-treasure"){const item=Config.SEWER_TREASURES.find(value=>value.id===id),done=core.state.sewer.maze.treasures[id];return{title:item.name,icon:"🎁",className:"narrow",body:`<div class="dialog-body"><p>A one-time sewer treasure. It cannot be duplicated by reopening this panel.</p><button class="primary-button" data-do="collect-sewer-treasure" data-id="${id}" ${done?"disabled":""}>${done?"Already collected":"Open treasure"}</button></div>`};}
  if(type==="mafia-symbol")return{title:"Six-Peel Graffiti",icon:"🍎",className:"narrow",body:`<div class="dialog-body"><p>A giant apple is ringed by six painted peels. One peel points toward an apparently solid wall.</p><button class="primary-button" data-do="inspect-mafia-symbol">Inspect hidden symbol</button></div>`};
  if(type==="mafia-bouncer")return{title:"Big Fig's Velvet Rope",icon:"🕴️",className:"narrow",body:`<div class="dialog-body"><p>“Fruit Mafia entry costs $100. Enter?” This is a one-time permanent fictional membership fee. Return visits are free.</p><div class="button-row"><button class="primary-button" data-do="mafia-membership" ${core.state.sewer.mafia.membership||!core.state.sewer.mafia.invitation?"disabled":""}>${core.state.sewer.mafia.membership?"Already a member":"Pay $100 and enter"}</button><button class="secondary-button" data-do="mafia-ask">Ask about the club</button></div><div class="button-row" style="margin-top:7px"><button class="secondary-button" data-do="mafia-show-invitation" ${core.state.sewer.mafia.invitation?"":"disabled"}>Show an invitation</button><button class="secondary-button" data-action="close-dialog">Leave</button></div></div>`};
  if(type==="sewer-character"){const character=Config.SEWER_CHARACTERS.find(value=>value.id===id),progress=core.state.sewer.characters[id];return{title:character.name,icon:character.icon,className:"narrow",kicker:character.role.toUpperCase(),body:`<div class="dialog-body"><p>${escapeHtml(character.dialogue)}</p><div class="tag-row"><span class="tag">${progress.met?"Known contact":"New character"}</span><span class="tag">Remembers ${progress.dialogue.length} conversation${progress.dialogue.length===1?"":"s"}</span></div><button class="primary-button" data-do="talk-sewer-character" data-id="${id}">Talk and ask for a clue</button></div>`};}
  return renderSewer();
}

function renderTree(treeId){const tree=core.state.trees.find(item=>item.id===treeId);if(!tree)return renderFruitBook();const fruit=Config.FRUIT_BY_ID[tree.fruit]||Config.FRUIT_BY_ID.apple,ripe=["ripe","golden"].includes(tree.status);return{title:`${fruit.name} Tree`,icon:tree.golden?"🌟":"🌳",className:"narrow",body:`<div class="dialog-body">${statStrip([["State",tree.status.replace("-"," ")],["Fruit",fruit.name],["Harvests",tree.harvests||0],["Watered",tree.watered?"Yes":"No"],["Fertilized",tree.fertilized?"Yes":"No"]])}<div class="game-card"><span class="big-icon">${fruit.icon}</span><h3>${ripe?"Ready to harvest":tree.diseased?"Treatment needed":`${remaining(tree.readyAt)}s until ripe`}</h3><p>Manual care improves yield and quality. Manual harvesting can award Research Points, XP, Fruit Coins, event fruit, and special quality.</p><button data-do="harvest-tree" data-id="${tree.id}" ${ripe?"":"disabled"}>${ripe?"Pick fruit":"Not ripe yet"}</button><div class="button-row" style="margin-top:8px"><button data-do="tree-care" data-id="${tree.id}" data-value="water">Water</button><button data-do="tree-care" data-id="${tree.id}" data-value="fertilize">Fertilize · $2</button><button data-do="tree-care" data-id="${tree.id}" data-value="treat">Treat disease · $3</button></div></div></div>`};}

function renderMoreObjectAction(id){const routes={"wall-map":["map",null],"employee-board":["office","workers"],"research-board":["more","research"],computer:["phone","messages"],"accountant-desk":["phone","company-bank"],"assistant-desk":["office","recruiting"],"trophy-cabinet":["more","achievements"],"company-safe":["office","overview"],elevator:["map",null]};const route=routes[id];if(route)return openPage(route[0],route[1]);if(id==="player-desk"||id==="chair"||id==="meeting-table"||id==="break-area"){const pip=core.state.workers["pip-orchard"];pip.happiness=clamp(pip.happiness+2,0,100);feedback(core.result(true,"A quick office check-in raised team happiness."),"Office conversation");return rerender();}feedback(core.result(true,"This office object stores company records and improves the room."),"Office object");}

function handleWorldInteraction(entity){if(entity.type==="tree")return openPage("tree",entity.id);if(entity.type==="district")return openPage("district",entity.id);if(entity.type==="crate"){feedback(core.collectDistrictCrate(entity.id),"Hidden crate");return;}if(entity.type==="worker")return openPage("worker",entity.id);if(entity.type==="applicant")return openPage("applicant",entity.id);if(entity.type==="manhole")return openPage("manhole",entity.id);if(["sewer-exit","sewer-map","water-point","sewer-lab","sewer-valve","sewer-gate","sewer-shortcut","sewer-treasure","sewer-character","mafia-bouncer","mafia-symbol","plinko","fruit-slots","future-mafia-game"].includes(entity.type))return openPage("sewer-object",`${entity.type}:${entity.id}`);if(entity.type==="building"){const building=Config.BUILDING_BY_ID[entity.id],owned=core.state.buildings[entity.id];if(building.category==="Entertainment"){const cooldown=60000,last=owned.lastVisitAt||0;if(Date.now()-last<cooldown)return feedback(core.result(false,`${Math.ceil((cooldown-(Date.now()-last))/1000)} seconds until the next visitor group.`),building.name);owned.lastVisitAt=Date.now();const tickets=owned.level*2;core.state.tickets+=tickets;core.earnCash(owned.level*5,`${building.name} visitors`);core.addXp(owned.level*3);return feedback(core.result(true,`Visitors enjoyed ${building.name} and earned ${tickets} tickets.`),"Attraction visit");}toast(building.name,`${building.description} Level ${owned?.level||1}.`);}}

function handleAction(button){const action=button.dataset.action;if(action==="close-dialog")return closeDialog();if(action==="find-player")return world.findPlayer();if(action==="zoom-in")return world.zoom(.12);if(action==="zoom-out")return world.zoom(-.12);if(action==="open-map")return openPage("map");if(action==="toggle-sound"){core.state.settings.sound=!core.state.settings.sound;updateUI();save();}}
function handleDo(button){
  const action=button.dataset.do,id=button.dataset.id,value=button.dataset.value,index=Number(button.dataset.index);let result=null;
  if(action==="subpage")return openPage(currentView.page,value,true);if(action==="phone-app")return openPage("phone",value,true);if(action==="route-page")return openPage(value,button.dataset.sub||null,true);if(action==="go-office-upgrades")return openPage("office","upgrades",true);
  if(action==="harvest-tree"){result=core.harvestTree(id,true);tone(result.ok?"harvest":"error");}
  else if(action==="tree-care")result=core.careForTree(id,value);
  else if(action==="sell-fruit")result=core.sellFruit(id,1);
  else if(action==="sell-product")result=core.sellProduct(id,1);
  else if(action==="feature")result=core.setFeatured(button.dataset.kind,id);
  else if(action==="market-stall")result=core.assignMarketStall(button.dataset.kind,id);
  else if(action==="district-upgrade")result=core.buyDistrictUpgrade(id,index);
  else if(action==="collect-crate")result=core.collectDistrictCrate(id);
  else if(action==="teleport"){result=core.teleport(id);if(result.ok){world.findPlayer();closeDialog();}}
  else if(action==="build-building")result=core.buildBuilding(id);
  else if(action==="upgrade-building")result=core.upgradeBuilding(id);
  else if(action==="lab-study")result=core.runLabStudy(id);
  else if(action==="craft")result=core.craft(id,1);
  else if(action==="start-production")result=core.startProduction(id,1);
  else if(action==="collect-production")result=core.collectProduction(id);
  else if(action==="hybrid"){const hybrid=Config.HYBRIDS.find(item=>item.id===id);result=core.startHybrid(...hybrid.parents);}
  else if(action==="resolve-research")result=core.resolveResearch(id);
  else if(action==="buy-vehicle")result=core.purchaseVehicle(id);
  else if(action==="dispatch")result=core.dispatchRoute(id);
  else if(action==="complete-delivery")result=core.completeDelivery(id);
  else if(action==="worker-action"){const data=value==="assign"?{assignment:$("#workerAssignment")?.value}:{topic:value==="talk"?"Thanks for checking in. I have a new idea for the team!":undefined};result=core.manageWorker(id,value,data);}
  else if(action==="worker-visit")result=core.respondWorkerVisit(id,value);
  else if(action==="office-upgrade")result=core.buyOfficeUpgrade(id);
  else if(action==="office-object")return renderMoreObjectAction(id);
  else if(action==="create-job-ad")return openJobAdForm();
  else if(action==="submit-job-ad")return submitJobAd();
  else if(action==="applicant"){const data=value==="trial"?{task:"Serving fruit-stand customers"}:value==="offer"?{salary:Number($("#offerSalary")?.value),position:$("#offerPosition")?.value,department:"Office",training:"Mentored introduction"}:{};result=core.applicantAction(id,value,data);if($("#hiringNotes"))core.state.applicants[id].notes=$("#hiringNotes").value;}
  else if(action==="interview-answer")result=core.applicantAction(id,"answer",{tone:value,good:true});
  else if(action==="respond-message")result=core.respondMessage(id,value);
  else if(action==="generate-order"){core.generateOrder();result=core.result(true,"A new fictional customer order arrived.");}
  else if(action==="order-negotiate")result=core.negotiateOrder(id,value);
  else if(action==="supply-order")result=core.supplyOrder(id);
  else if(action==="collect-payment")result=core.collectPayment(id);
  else if(action==="buy-market-fruit"){const price=Number(button.dataset.price);if(!core.canStoreFruit(1))result=core.result(false,"Basket is full.");else{const paid=core.spend({cash:price});if(paid.ok){core.state.fruitInventory[id]=(core.state.fruitInventory[id]||0)+1;core.state.discoveredFruit[id]=true;result=core.result(true,`Bought one ${fruitName(id)} for ${money(price)}.`);}else result=paid;}}
  else if(action==="contact-message"){core.state.phone.messages.unshift({id:`contact-${Date.now()}`,from:value,subject:"Fruitopia greeting",body:"Thanks for reaching out. I will remember your company kindness.",unread:true,responses:["Keep in touch"]});result=core.result(true,`Message sent to ${value}.`);}
  else if(action==="invest")result=core.invest(id,25);
  else if(action==="collect-investment")result=core.collectInvestment(id);
  else if(action==="start-minigame")return openPage("arcade",`play:${id}`,true);
  else if(action==="end-minigame"){minigame?.finish();return;}
  else if(action==="start-event")result=core.startEvent(id);
  else if(action==="secret")result=core.investigateSecret(id,value);
  else if(action==="claim-quest")result=core.claimQuest(id);
  else if(action==="claim-milestone")result=core.claimMilestone(id);
  else if(action==="buy-permanent")result=core.buyPermanent(id);
  else if(action==="season-confirm")return openConfirmSeason();
  else if(action==="season-reset"){result=core.beginSeason();if(result.ok){world.core=core;closeDialog();}}
  else if(action==="manhole")result=core.inspectManhole(id,value);
  else if(action==="enter-sewer"){result=core.enterSewer(id);if(result.ok){tone("harvest");world.target=null;world.camera={x:core.state.sewer.player.x,y:core.state.sewer.player.y,zoom:1.15};closeDialog();world.findPlayer();}}
  else if(action==="leave-sewer"){result=core.leaveSewer();if(result.ok){world.target=null;world.camera={x:core.state.player.x,y:core.state.player.y,zoom:1};closeDialog();world.findPlayer();}}
  else if(action==="find-sewer-player"){world.findPlayer();closeDialog();return;}
  else if(action==="collect-green-water")result=core.collectGreenWater(id,$("#waterContainer")?.value);
  else if(action==="start-sewer-experiment"){result=core.startSewerExperiment({sampleId:$("#sewerSample")?.value,ingredient:$("#sewerIngredient")?.value,additional:$("#sewerAdditional")?.value,intensity:$("#sewerIntensity")?.value,duration:$("#sewerDuration")?.value,purify:$("#sewerPurify")?.checked});}
  else if(action==="collect-sewer-experiment")result=core.collectSewerExperiment(id);
  else if(action==="study-maze-map")result=core.studyMazeMap();
  else if(action==="turn-sewer-valve")result=core.turnSewerValve(id);
  else if(action==="unlock-sewer-gate")result=core.unlockSewerGate(id);
  else if(action==="open-sewer-shortcut")result=core.openSewerShortcut(id);
  else if(action==="collect-sewer-treasure")result=core.collectSewerTreasure(id);
  else if(action==="inspect-mafia-symbol")result=core.inspectMafiaSymbol();
  else if(action==="talk-sewer-character")result=core.talkSewerCharacter(id);
  else if(action==="mafia-ask")result=core.result(true,"Big Fig says the club is a harmless fruit-fan society. The $100 fictional Cash fee is paid once; machines use non-purchasable Club Chips with posted limits.");
  else if(action==="mafia-show-invitation")result=core.result(core.state.sewer.mafia.invitation,core.state.sewer.mafia.invitation?"Big Fig nods. The invitation grants permission to buy permanent membership; the one-time fee remains $100.":"Find an invitation in the maze first.");
  else if(action==="mafia-membership")result=core.buyMafiaMembership();
  else if(action==="mafia-start")result=mafiaGame.startRound(Number($("#mafiaOpponents")?.value||3),$("#mafiaFamily")?.checked!==false);
  else if(action==="mafia-next")result=mafiaGame.advanceTurn();
  else if(action==="mafia-decision")result=mafiaGame.decide(value,value);
  else if(action==="mafia-card")result=mafiaGame.playCard(id,$("#mafiaCardTarget")?.value||null);
  else if(action==="mafia-collect")result=mafiaGame.collectReward();
  else if(action==="mafia-new-round"){core.state.sewer.mafiaGame.status="idle";core.state.sewer.mafiaGame.event=null;core.state.sewer.mafiaGame.pending=null;result=core.result(true,"The Mystery Crate room is ready for another round.");}
  else if(action==="plinko-drop")result=core.startPlinko(Number($("#plinkoPosition")?.value||3));
  else if(action==="collect-plinko")result=core.collectPlinko(id);
  else if(action==="spin-slots")result=core.startFruitSlots();
  else if(action==="collect-slots")result=core.collectFruitSlots(id);
  else if(action==="claim-sewer-quest")result=core.claimSewerQuest(id);
  else if(action==="sewer-secret")result=core.investigateSewerSecret(id,value);
  else if(action==="buy-sewer-aid")result=core.purchaseSewerAid(id);
  else if(action==="use-return-token"){result=core.useEmergencyReturn();if(result.ok){world.findPlayer();closeDialog();}}
  else if(action==="setting"){core.state.settings[id]=!core.state.settings[id];if(id==="music")updateMusic();result=core.result(true,`${id} ${core.state.settings[id]?"enabled":"disabled"}.`);}
  else if(action==="reset-save-confirm")return openResetConfirm();
  else if(action==="reset-save"){localStorage.removeItem(Config.SAVE_KEY);core.state=createDefaultState();world.core=core;closeDialog();updateUI();save();return toast("New Fruitopia game","Local progress reset safely.");}
  if(result){feedback(result,action.includes("buy")||action.includes("upgrade")||action.includes("build")?"Company updated":action.includes("sewer")||action.includes("plinko")||action.includes("slot")||action.includes("mafia")?"Under Fruitopia":"Fruitopia");if(currentView.page)rerender();if(result.ok&&["start-sewer-experiment","plinko-drop","spin-slots"].includes(action)){const wait=action==="start-sewer-experiment"?Math.max(100,(core.state.sewer.lab.activeExperiment?.readyAt||Date.now())-Date.now()+50):action==="plinko-drop"?(core.state.sewer.plinko.pending?.readyAt||Date.now())-Date.now()+80:(core.state.sewer.slots.pending?.readyAt||Date.now())-Date.now()+80;setTimeout(()=>{if(["sewer","sewer-object"].includes(currentView.page))rerender();},wait);}}
}

function openJobAdForm(){openDialog("Create Job Advertisement","📣",`<div class="dialog-body"><div class="card-grid two"><label>Job title<input id="jobTitle" class="field" value="Orchard Team Member"></label><label>Department<select id="jobDepartment" class="field"><option>Orchard</option><option>Stand and Market</option><option>Production</option><option>Delivery</option><option>Laboratory</option><option>Office</option><option>Entertainment</option></select></label><label>Experience level<select id="jobExperience" class="field"><option>Entry</option><option>Experienced</option><option>Expert</option></select></label><label>Salary range<input id="jobSalary" class="field" type="number" min="1" value="15"></label><label>Required skills<input id="jobSkills" class="field" value="Teamwork, friendly service"></label><label>Schedule<select id="jobSchedule" class="field"><option>Flexible</option><option>Morning</option><option>Evening</option></select></label><label>Employment<select id="jobEmployment" class="field"><option>Full-time</option><option>Part-time</option><option>Seasonal</option><option>Temporary</option></select></label><label>Advertisement style<select id="jobStyle" class="field"><option>Friendly</option><option>Professional</option><option>Playful</option><option>Bold</option></select></label><label>Location<select id="jobLocation" class="field"><option>Town noticeboard</option><option>Local newspaper</option><option>Fruitopia employment app</option><option>Employment agency</option><option>School recruiting</option><option>Radio advertisement</option><option>Social campaign</option><option>National campaign</option><option>Job fair</option></select></label><label>Campaign length<input id="jobDays" class="field" type="number" min="1" max="14" value="3"></label></div><button class="primary-button" style="margin-top:12px" data-do="submit-job-ad">Launch fictional campaign</button></div>`,{className:"narrow"});currentView={page:"office",sub:"recruiting"};}
function submitJobAd(){const result=core.createJobAd({title:$("#jobTitle").value,department:$("#jobDepartment").value,experience:$("#jobExperience").value,salary:$("#jobSalary").value,skills:$("#jobSkills").value,schedule:$("#jobSchedule").value,employment:$("#jobEmployment").value,style:$("#jobStyle").value,location:$("#jobLocation").value,days:$("#jobDays").value,training:true});feedback(result,"Recruiting");openPage("office","recruiting",true);}
function openConfirmSeason(){openDialog("Begin a new season?","🌟",`<div class="dialog-body"><section class="notice danger"><strong>This reset is permanent.</strong> Ordinary Cash, upgrades, district construction, inventory, active production, and fleet progress will reset. Preserved legacy progress is listed on the Season screen.</section><div class="button-row" style="margin-top:12px"><button class="secondary-button" data-nav="season">Keep this season</button><button class="danger-button" data-do="season-reset">Confirm new season</button></div></div>`,{className:"narrow"});currentView={page:"season",sub:null};}
function openResetConfirm(){openDialog("Reset local Fruitopia save?","⚠️",`<div class="dialog-body"><section class="notice danger">This removes the current local save from this browser. This cannot be undone.</section><div class="button-row" style="margin-top:12px"><button class="secondary-button" data-action="close-dialog">Cancel</button><button class="danger-button" data-do="reset-save">Delete save and restart</button></div></div>`,{className:"narrow"});currentView={page:"more",sub:"settings"};}

document.addEventListener("click",event=>{const nav=event.target.closest("[data-nav]");if(nav){event.preventDefault();const page=nav.dataset.nav,sub=nav.dataset.page||nav.dataset.id||null;openPage(page,sub);return;}const action=event.target.closest("[data-action]");if(action){event.preventDefault();handleAction(action);return;}const operation=event.target.closest("[data-do]");if(operation){event.preventDefault();handleDo(operation);}});
$("#dialogLayer").addEventListener("pointerdown",event=>{if(event.target===$("#dialogLayer"))closeDialog();});
window.addEventListener("keydown",event=>{
  if(event.key==="Escape"&&!$("#dialogLayer").classList.contains("hidden")){event.preventDefault();closeDialog();return;}
  if(event.key==="Tab"&&!$("#dialogLayer").classList.contains("hidden")){const focusable=$$("button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex='0']",$("#dialog"));if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
  if(currentView.page==="office"&&(currentView.sub||"overview")==="overview"&&!$("#dialogLayer").classList.contains("hidden")&&!/INPUT|SELECT|TEXTAREA/.test(document.activeElement?.tagName||"")){const key=event.key.toLowerCase(),moves={w:[0,-3],arrowup:[0,-3],s:[0,3],arrowdown:[0,3],a:[-3,0],arrowleft:[-3,0],d:[3,0],arrowright:[3,0]};if(moves[key]){event.preventDefault();core.state.office.player.x=clamp(core.state.office.player.x+moves[key][0],2,92);core.state.office.player.y=clamp(core.state.office.player.y+moves[key][1],5,88);positionOfficePlayer();}}
});
$("#touchPad").addEventListener("pointerdown",event=>{const button=event.target.closest("[data-move]");if(button){event.preventDefault();world.moveDirection(button.dataset.move);}});

world=new FruitopiaWorld($("#world"),core,{onInteract:handleWorldInteraction,onMove:player=>{if(core.state.sewer.active){core.updateSewerLocation(player);return;}const nearest=Config.DISTRICTS.slice().sort((a,b)=>Math.hypot(player.x-a.x,player.y-a.y)-Math.hypot(player.x-b.x,player.y-b.y))[0];if(Math.hypot(player.x-nearest.x,player.y-nearest.y)<13)player.district=nearest.id;},onPrompt:text=>{$("#worldHint").textContent=text;}});
window.__FRUITOPIA__={core,Config,world,mafiaGame,openPage,save,createDefaultState,migrateSave};

updateUI();updateMusic();if(offline.elapsed>2)toast("Welcome back",offline.message);setInterval(()=>{const timedOut=mafiaGame.handleTimeout(Date.now());core.advanceTime(Date.now());updateUI();if(timedOut&&["mafia-game","sewer-object"].includes(currentView.page))rerender();},1000);setInterval(()=>{if(core.state.settings.autosave)save();},10000);window.addEventListener("beforeunload",save);save();

function renderMafiaClubWithMystery(){
  const original=renderMafiaClub();if(!core.state.sewer.mafia.membership)return original;
  const room=`<section class="private-room mystery-room"><span>📦</span><div><h3>Fruit Mafia: The Mystery Crate</h3><p>Don Durian hosts an original one-hit survival game for you and 3–9 strategic computer opponents. Crate events create every danger; cards provide timing, protection, redirection, and bluffing.</p><button class="primary-button" data-nav="mafia-game">Enter Mystery Crate room</button></div></section>`;
  return original.replace(/<section class="private-room">[\s\S]*?<\/section>/,room);
}

function mafiaDecisionMarkup(pending,state){
  if(!pending)return "";const participants=state.participants,person=id=>participants.find(item=>item.id===id);
  const button=(value,label,extra="")=>`<button class="crate-choice" data-do="mafia-decision" data-value="${escapeHtml(value)}" ${extra}>${label}</button>`;
  let choices="";
  if(pending.type==="card-choice")choices=pending.choices.map(id=>{const card=Config.MAFIA_CARD_BY_ID[id];return `<button class="mafia-card choice ${card.alignment.toLowerCase()}" data-do="mafia-decision" data-value="${id}"><span>${card.icon}</span><strong>${escapeHtml(card.name)}</strong><small>${card.alignment} · ${card.activation}</small><p>${escapeHtml(card.description)}</p></button>`;}).join("");
  else if(pending.type==="reaction")choices=pending.options.map(option=>button(option,({"rebound-left":"↩️ Rebound left","rebound-right":"Rebound right ↪️","blade-back":"↪️ Rebound Blade","side-step":"🪑 Side Step",dodge:"💨 Banana Dodge","take-hit":"No reaction"})[option]||escapeHtml(option))).join("");
  else if(pending.type==="knife-target")choices=pending.options.map(option=>{if(option==="spare")return button(option,"🕊️ Spare Them");const id=option==="left"?pending.leftId:option==="right"?pending.rightId:option,target=person(id),direction=option==="left"?"⬅️":option==="right"?"➡️":"👆";return button(option,`${direction} ${escapeHtml(target?.name||option)}`);}).join("");
  else if(["target-card","vote"].includes(pending.type))choices=pending.targets.map(id=>{const target=person(id);return button(id,`${target?.avatar||"🍎"} ${escapeHtml(target?.name||id)}`);}).join("");
  else if(pending.type==="dangerous-pile")choices=pending.options.map(index=>button(String(index),`🂠 Pile ${Number(index)+1}`)).join("");
  else choices=(pending.options||[]).map(option=>button(option,({accept:"Accept the risk",refuse:"Refuse safely",share:"Share",snatch:"Snatch",contribute:"Contribute a card",wait:"Wait for help",steady:"Steady aim",quick:"Quick draw",dodge:"Dodge first","apple-chair":"🍎 Apple chair","grape-chair":"🍇 Grape chair","lemon-chair":"🍋 Lemon chair",open:"Open the crate",leave:"Leave it closed"})[option]||escapeHtml(option))).join("");
  return `<section class="crate-decision" aria-live="polite"><small>YOUR DECISION · ${pending.seconds||12} SECOND WINDOW</small><div class="decision-timer" style="--seconds:${pending.seconds||12}s"><i></i></div><h3>${escapeHtml(pending.prompt)}</h3><div class="crate-choices ${pending.type==="card-choice"?"card-choices":""}">${choices}</div></section>`;
}

function renderMafiaGame(){
  const state=core.state.sewer.mafiaGame,member=core.state.sewer.mafia.membership;
  if(!member)return{title:"Fruit Mafia: The Mystery Crate",icon:"📦",className:"narrow",kicker:"FRUIT MAFIA CLUB",body:`<div class="dialog-body"><section class="notice danger"><strong>Members-only room.</strong> Find an invitation and purchase the permanent $100 fictional-Cash club membership first.</section><button class="secondary-button" style="margin-top:10px" data-nav="sewer" data-page="club">Return to the club entrance</button></div>`};
  if(state.status==="idle")return{title:"Fruit Mafia: The Mystery Crate",icon:"📦",kicker:"DON DURIAN'S PRIVATE ROOM",body:`<div class="dialog-body mafia-intro"><section class="notice"><strong>Original Fruitopia survival game.</strong> No real money, cash-out, realistic injury, or unrestricted attacks. Mystery Crate events create danger; the last fruit sitting wins.</section><div class="mafia-stage-preview"><div class="hanging-lights">●　●　●</div><div class="host-portrait">🥭<strong>DON DURIAN</strong><small>“The crate chooses. You choose when to use your cards.”</small></div><div class="preview-table"><span>📦</span></div></div>${statStrip([["Entry",`${Config.MAFIA_GAME.entryCost} Club Chips`],["Your chips",core.state.sewer.mafia.clubChips],["Opponents","3–9 AI"],["Elimination","One hit"],["Cards",Config.MAFIA_CARDS.length]])}<div class="card-grid two"><article class="game-card"><h3>Round rules</h3><p>Everyone starts with two cards. The crate creates a different event each turn. Automatic, passive, manual, and reaction cards change what happens. Eliminated players watch from the spectator rail.</p></article><article class="game-card"><h3>Original & family-friendly</h3><p>Enable silly-object mode for Fruit Launchers, Spring Bananas, Spinning Pizza Cutters, and giant juice splashes. No blood or graphic injury appears.</p></article></div><div class="mafia-setup"><label>Computer opponents<select id="mafiaOpponents" class="field">${Array.from({length:7},(_,index)=>`<option value="${index+3}" ${index===0?"selected":""}>${index+3} opponents</option>`).join("")}</select></label><label class="check-field"><input id="mafiaFamily" type="checkbox" checked> Family-friendly silly objects</label><button class="primary-button" data-do="mafia-start">Start round · ${Config.MAFIA_GAME.entryCost} Club Chips</button></div><details class="mafia-rules"><summary>Card and event guide</summary><div class="card-grid two"><article><h3>${Config.MAFIA_CARDS.length} cards</h3><p>${Config.MAFIA_CARDS.map(card=>`${card.icon} ${escapeHtml(card.name)}`).join(" · ")}</p></article><article><h3>${Config.MAFIA_EVENTS.length} crate events</h3><p>${Config.MAFIA_EVENTS.map(event=>`${event.icon} ${escapeHtml(event.name)}`).join(" · ")}</p></article></div></details></div>`};
  const participants=state.participants||[],human=participants.find(item=>item.human),living=participants.filter(item=>item.alive),spectators=participants.filter(item=>!item.alive),event=state.event,pending=state.pending,count=participants.length;
  const seats=participants.map(participant=>`<article class="mafia-seat ${participant.human?"human":""} ${participant.alive?"":"eliminated"}" style="--seat:${participant.seat};--count:${count}" aria-label="${escapeHtml(participant.name)}, ${participant.alive?"active":"spectating"}"><span>${participant.avatar}</span><strong>${escapeHtml(participant.name)}</strong><small>${participant.alive?`${participant.hand.length} cards`:"SPECTATOR"}</small></article>`).join("");
  if(state.status==="finished"){const reward=state.reward;return{title:"Fruit Mafia: The Mystery Crate",icon:"🏆",kicker:"ROUND COMPLETE",body:`<div class="dialog-body"><div class="mafia-finale"><span>${reward.won?"🏆":"🎭"}</span><h2>${escapeHtml(reward.winner)} is the last fruit sitting!</h2><p>${reward.won?"You outlasted Don Durian's crate.":"You joined the spectator rail, but your survival rewards are ready."}</p></div>${statStrip([["Turns",state.turn],["Winner",reward.winner],["Club Chips",`+${reward.chips}`],["Cash",`+$${reward.cash}`],["XP",`+${reward.xp}`]])}<button class="primary-button" data-do="mafia-collect" ${state.rewardCollected?"disabled":""}>${state.rewardCollected?"Round reward collected":"Collect round reward once"}</button><button class="secondary-button" style="margin-top:8px" data-do="mafia-new-round">Return to game setup</button><h3>Final event history</h3><div class="mafia-history">${state.history.slice(-16).reverse().map(item=>`<p class="${item.tone}"><b>Turn ${item.turn}</b> ${escapeHtml(item.message)}</p>`).join("")}</div></div>`};}
  const targetOptions=living.filter(item=>!item.human).map(item=>`<option value="${item.id}">${item.avatar} ${escapeHtml(item.name)}</option>`).join("");
  const hand=(human?.hand||[]).map(instance=>{const card=Config.MAFIA_CARD_BY_ID[instance.cardId],manual=card.activation==="Manual";return `<article class="mafia-card ${card.alignment.toLowerCase()}"><span>${card.icon}</span><strong>${escapeHtml(card.name)}</strong><small>${card.alignment} · ${card.activation}${instance.remainingTurns?` · ${instance.remainingTurns} turns`:""}</small><p>${escapeHtml(card.description)}</p>${manual?`<button data-do="mafia-card" data-id="${instance.instanceId}">Use card</button>`:`<em>${card.activation==="Reaction"?"Available during its reaction window":card.activation==="Automatic"?"Activates when triggered":"Effect is active"}</em>`}</article>`;}).join("")||"<div class='empty-state'>Your hand is empty. Watch for a Choose a Card event.</div>";
  return{title:"Fruit Mafia: The Mystery Crate",icon:"📦",kicker:`TURN ${state.turn} · ${living.length} FRUITS SITTING`,body:`<div class="dialog-body mafia-game"><section class="mafia-room"><div class="mafia-pipes"></div><div class="hanging-lights">●　●　●</div><div class="mafia-host"><span>🥭</span><strong>Don Durian</strong><small>${event?`${event.icon} ${escapeHtml(event.name)}`:"The crate is waiting."}</small></div><div class="mafia-table" aria-label="Round table with players and Mystery Crate"><div class="mystery-crate ${event?.status==="active"?"active":""}"><span>${event?.icon||"📦"}</span><strong>${event?escapeHtml(event.name):"MYSTERY CRATE"}</strong></div>${seats}</div><aside class="spectator-rail"><strong>👀 Spectator rail</strong><span>${spectators.map(item=>escapeHtml(item.name)).join(" · ")||"Empty"}</span></aside></section>${mafiaDecisionMarkup(pending,state)}${!pending?`<button class="crate-lever" data-do="mafia-next">${event?.status==="resolved"||event?"Pull for next crate event":"Open the Mystery Crate"}</button>`:""}<div class="mafia-dashboard">${statStrip([["Alive",`${living.length}/${count}`],["Turn",state.turn],["Your cards",human?.hand.length||0],["Rebounds",human?.stats.rebounds||0],["Club Chips",core.state.sewer.mafia.clubChips]])}<label>Manual-card target<select id="mafiaCardTarget" class="field">${targetOptions||"<option>No living opponents</option>"}</select></label></div><h3>Your cards</h3><div class="mafia-hand">${hand}</div><div class="mafia-lower"><section><h3>Event history</h3><div class="mafia-history" aria-live="polite">${state.history.slice(-12).reverse().map(item=>`<p class="${item.tone}"><b>Turn ${item.turn}</b> ${escapeHtml(item.message)}</p>`).join("")}</div></section><section><h3>Opponent tells</h3>${participants.filter(item=>!item.human).map(item=>`<article class="opponent-tell"><span>${item.avatar}</span><div><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.personality)} · ${Math.round(item.risk*100)}% risk tolerance</small><p>${escapeHtml(item.dialogue)}</p></div></article>`).join("")}</section></div></div>`};
}
